export const questions: Question[] = [
  { id: "y2in2-001", topicRef: "y2in2", topicTitle: "Integrating f(ax + b) 01", difficulty: "Standard", answerType: "expression", questionText: "Find \\( \\displaystyle\\int \\left(2x + 1\\right)^5 \\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["linear-inner", "power"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-inner-argument rule.", workingLatex: "\\displaystyle\\int \\left(ax + b\\right)^{n}\\,dx = \\frac{\\left(ax + b\\right)^{n+1}}{a\\left(n+1\\right)} + C \\quad \\left(n \\ne -1\\right)", explanation: "For an integrand whose only \\(x\\)-dependence is a linear bracket raised to a power, integrate as if the argument were \\(x\\) (giving \\(\\left(ax+b\\right)^{n+1}/\\left(n+1\\right)\\)), then divide by the inner coefficient \\(a\\) to undo the chain rule. The exclusion \\(n = -1\\) avoids dividing by \\(n+1 = 0\\) — that case uses the log rule." }, { stepNumber: 2, description: "Identify \\(a = 2\\), \\(n = 5\\).", workingLatex: "a = 2,\\quad n = 5 \\;\\Rightarrow\\; n + 1 = 6,\\quad a\\left(n+1\\right) = 12", explanation: "Read the constants off the bracket: \\(a\\) is the coefficient of \\(x\\) inside, \\(n\\) is the outer exponent. The denominator is their product." }, { stepNumber: 3, description: "Apply the formula.", workingLatex: "\\displaystyle\\int \\left(2x + 1\\right)^5\\,dx = \\frac{\\left(2x + 1\\right)^6}{12} + C", explanation: "Check: \\(\\frac{d}{dx}\\!\\left[\\frac{\\left(2x+1\\right)^6}{12}\\right] = \\frac{6\\left(2x+1\\right)^5 \\cdot 2}{12} = \\left(2x+1\\right)^5\\) ✓." } ], finalAnswer: "\\(\\frac{\\left(2x+1\\right)^6}{12} + C\\)." } },
  { id: "y2in2-002", topicRef: "y2in2", topicTitle: "Integrating f(ax + b) 02", difficulty: "Foundation", answerType: "expression", questionText: "Find \\( \\displaystyle\\int \\left(3x - 4\\right)^2 \\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["linear-inner", "power"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-inner-argument rule.", workingLatex: "\\displaystyle\\int \\left(ax + b\\right)^{n}\\,dx = \\frac{\\left(ax + b\\right)^{n+1}}{a\\left(n+1\\right)} + C \\quad \\left(n \\ne -1\\right)", explanation: "For an integrand whose only \\(x\\)-dependence is a linear bracket raised to a power, integrate as if the argument were \\(x\\) (giving \\(\\left(ax+b\\right)^{n+1}/\\left(n+1\\right)\\)), then divide by the inner coefficient \\(a\\) to undo the chain rule. The exclusion \\(n = -1\\) avoids dividing by \\(n+1 = 0\\) — that case uses the log rule." }, { stepNumber: 2, description: "Identify \\(a = 3\\), \\(n = 2\\).", workingLatex: "a = 3,\\quad n = 2 \\;\\Rightarrow\\; a\\left(n+1\\right) = 9", explanation: "Inner: \\(3x - 4\\). Outer: squared." }, { stepNumber: 3, description: "Apply the formula.", workingLatex: "\\displaystyle\\int \\left(3x - 4\\right)^2\\,dx = \\frac{\\left(3x - 4\\right)^3}{9} + C", explanation: "Check: \\(\\frac{d}{dx}\\frac{\\left(3x-4\\right)^3}{9} = \\frac{3\\left(3x-4\\right)^2 \\cdot 3}{9} = \\left(3x-4\\right)^2\\) ✓." } ], finalAnswer: "\\(\\frac{\\left(3x-4\\right)^3}{9} + C\\)." } },
  { id: "y2in2-003", topicRef: "y2in2", topicTitle: "Integrating f(ax + b) 03", difficulty: "Foundation", answerType: "expression", questionText: "Find \\( \\displaystyle\\int \\left(x + 5\\right)^4 \\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["linear-inner", "power"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-inner-argument rule.", workingLatex: "\\displaystyle\\int \\left(ax + b\\right)^{n}\\,dx = \\frac{\\left(ax + b\\right)^{n+1}}{a\\left(n+1\\right)} + C \\quad \\left(n \\ne -1\\right)", explanation: "For an integrand whose only \\(x\\)-dependence is a linear bracket raised to a power, integrate as if the argument were \\(x\\) (giving \\(\\left(ax+b\\right)^{n+1}/\\left(n+1\\right)\\)), then divide by the inner coefficient \\(a\\) to undo the chain rule. The exclusion \\(n = -1\\) avoids dividing by \\(n+1 = 0\\) — that case uses the log rule." }, { stepNumber: 2, description: "Identify \\(a = 1\\), \\(n = 4\\).", workingLatex: "a = 1,\\quad n = 4 \\;\\Rightarrow\\; a\\left(n+1\\right) = 5", explanation: "When \\(a = 1\\), the formula collapses to the plain power rule on the bracket — no extra division needed." }, { stepNumber: 3, description: "Apply the formula.", workingLatex: "\\displaystyle\\int \\left(x + 5\\right)^4\\,dx = \\frac{\\left(x + 5\\right)^5}{5} + C", explanation: "" } ], finalAnswer: "\\(\\frac{\\left(x+5\\right)^5}{5} + C\\)." } },
  { id: "y2in2-004", topicRef: "y2in2", topicTitle: "Integrating f(ax + b) 04", difficulty: "Standard", answerType: "expression", questionText: "Find \\( \\displaystyle\\int \\left(4 - x\\right)^3 \\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["linear-inner", "power"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-inner-argument rule.", workingLatex: "\\displaystyle\\int \\left(ax + b\\right)^{n}\\,dx = \\frac{\\left(ax + b\\right)^{n+1}}{a\\left(n+1\\right)} + C \\quad \\left(n \\ne -1\\right)", explanation: "For an integrand whose only \\(x\\)-dependence is a linear bracket raised to a power, integrate as if the argument were \\(x\\) (giving \\(\\left(ax+b\\right)^{n+1}/\\left(n+1\\right)\\)), then divide by the inner coefficient \\(a\\) to undo the chain rule. The exclusion \\(n = -1\\) avoids dividing by \\(n+1 = 0\\) — that case uses the log rule." }, { stepNumber: 2, description: "Rewrite the bracket so \\(a\\) and \\(b\\) are visible.", workingLatex: "\\left(4 - x\\right) = \\left(-1 \\cdot x + 4\\right) \\;\\Rightarrow\\; a = -1,\\; b = 4", explanation: "The coefficient of \\(x\\) is the crucial \\(a\\) — here it is \\(-1\\) because of the negative sign. Sign-tracking is the most common slip here." }, { stepNumber: 3, description: "Apply the formula.", workingLatex: "\\displaystyle\\int \\left(4 - x\\right)^3\\,dx = \\frac{\\left(4 - x\\right)^4}{\\left(-1\\right)\\left(4\\right)} + C = -\\frac{\\left(4 - x\\right)^4}{4} + C", explanation: "\\(a\\left(n+1\\right) = -4\\), so the leading minus when tidied." }, { stepNumber: 4, description: "Verify by differentiation.", workingLatex: "\\frac{d}{dx}\\!\\left[-\\frac{\\left(4 - x\\right)^4}{4}\\right] = -\\frac{4\\left(4 - x\\right)^3 \\cdot \\left(-1\\right)}{4} = \\left(4 - x\\right)^3 \\;\\checkmark", explanation: "The chain rule supplies the extra \\(\\times \\left(-1\\right)\\), which cancels the leading minus to give \\(+\\left(4-x\\right)^3\\)." } ], finalAnswer: "\\(-\\frac{\\left(4-x\\right)^4}{4} + C\\)." } },
  { id: "y2in2-005", topicRef: "y2in2", topicTitle: "Integrating f(ax + b) 05", difficulty: "Foundation", answerType: "expression", questionText: "Find \\( \\displaystyle\\int \\left(5x + 3\\right)^{10} \\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["linear-inner", "power"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-inner-argument rule.", workingLatex: "\\displaystyle\\int \\left(ax + b\\right)^{n}\\,dx = \\frac{\\left(ax + b\\right)^{n+1}}{a\\left(n+1\\right)} + C \\quad \\left(n \\ne -1\\right)", explanation: "For an integrand whose only \\(x\\)-dependence is a linear bracket raised to a power, integrate as if the argument were \\(x\\) (giving \\(\\left(ax+b\\right)^{n+1}/\\left(n+1\\right)\\)), then divide by the inner coefficient \\(a\\) to undo the chain rule. The exclusion \\(n = -1\\) avoids dividing by \\(n+1 = 0\\) — that case uses the log rule." }, { stepNumber: 2, description: "Identify \\(a = 5\\), \\(n = 10\\).", workingLatex: "a = 5,\\quad n = 10 \\;\\Rightarrow\\; a\\left(n+1\\right) = 55", explanation: "" }, { stepNumber: 3, description: "Apply the formula.", workingLatex: "\\displaystyle\\int \\left(5x + 3\\right)^{10}\\,dx = \\frac{\\left(5x + 3\\right)^{11}}{55} + C", explanation: "Same template; just bigger numbers." } ], finalAnswer: "\\(\\frac{\\left(5x+3\\right)^{11}}{55} + C\\)." } },
  { id: "y2in2-006", topicRef: "y2in2", topicTitle: "Integrating f(ax + b) 06", difficulty: "Standard", answerType: "expression", questionText: "Find \\( \\displaystyle\\int \\sqrt{2x - 1} \\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["linear-inner", "power", "root"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-inner-argument rule.", workingLatex: "\\displaystyle\\int \\left(ax + b\\right)^{n}\\,dx = \\frac{\\left(ax + b\\right)^{n+1}}{a\\left(n+1\\right)} + C \\quad \\left(n \\ne -1\\right)", explanation: "For an integrand whose only \\(x\\)-dependence is a linear bracket raised to a power, integrate as if the argument were \\(x\\) (giving \\(\\left(ax+b\\right)^{n+1}/\\left(n+1\\right)\\)), then divide by the inner coefficient \\(a\\) to undo the chain rule. The exclusion \\(n = -1\\) avoids dividing by \\(n+1 = 0\\) — that case uses the log rule." }, { stepNumber: 2, description: "Rewrite the radical as a fractional power.", workingLatex: "\\sqrt{2x - 1} = \\left(2x - 1\\right)^{\\tfrac{1}{2}}", explanation: "The power rule needs the bracket raised to a power, not under a root." }, { stepNumber: 3, description: "Identify \\(a = 2\\), \\(n = \\frac{1}{2}\\).", workingLatex: "a\\left(n+1\\right) = 2 \\cdot \\frac{3}{2} = 3", explanation: "" }, { stepNumber: 4, description: "Apply the formula.", workingLatex: "\\displaystyle\\int \\left(2x - 1\\right)^{\\tfrac{1}{2}}\\,dx = \\frac{\\left(2x - 1\\right)^{\\tfrac{3}{2}}}{3} + C", explanation: "" } ], finalAnswer: "\\(\\frac{\\left(2x-1\\right)^{\\tfrac{3}{2}}}{3} + C\\)." } },
  { id: "y2in2-007", topicRef: "y2in2", topicTitle: "Integrating f(ax + b) 07", difficulty: "Standard", answerType: "expression", questionText: "Find \\( \\displaystyle\\int \\frac{1}{\\left(3x + 2\\right)^2} \\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["linear-inner", "power"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-inner-argument rule.", workingLatex: "\\displaystyle\\int \\left(ax + b\\right)^{n}\\,dx = \\frac{\\left(ax + b\\right)^{n+1}}{a\\left(n+1\\right)} + C \\quad \\left(n \\ne -1\\right)", explanation: "For an integrand whose only \\(x\\)-dependence is a linear bracket raised to a power, integrate as if the argument were \\(x\\) (giving \\(\\left(ax+b\\right)^{n+1}/\\left(n+1\\right)\\)), then divide by the inner coefficient \\(a\\) to undo the chain rule. The exclusion \\(n = -1\\) avoids dividing by \\(n+1 = 0\\) — that case uses the log rule." }, { stepNumber: 2, description: "Rewrite as a negative power.", workingLatex: "\\frac{1}{\\left(3x + 2\\right)^2} = \\left(3x + 2\\right)^{-2}", explanation: "The power rule applies for any \\(n \\ne -1\\), including negative integers." }, { stepNumber: 3, description: "Identify \\(a = 3\\), \\(n = -2\\).", workingLatex: "a\\left(n+1\\right) = 3 \\cdot \\left(-1\\right) = -3", explanation: "" }, { stepNumber: 4, description: "Apply the formula and tidy.", workingLatex: "\\displaystyle\\int \\left(3x + 2\\right)^{-2}\\,dx = \\frac{\\left(3x + 2\\right)^{-1}}{-3} + C = -\\frac{1}{3\\left(3x + 2\\right)} + C", explanation: "" } ], finalAnswer: "\\(-\\frac{1}{3\\left(3x+2\\right)} + C\\)." } },
  { id: "y2in2-008", topicRef: "y2in2", topicTitle: "Integrating f(ax + b) 08", difficulty: "Standard", answerType: "expression", questionText: "Find \\( \\displaystyle\\int \\left(3x - 1\\right)^{-3} \\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["linear-inner", "power"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-inner-argument rule.", workingLatex: "\\displaystyle\\int \\left(ax + b\\right)^{n}\\,dx = \\frac{\\left(ax + b\\right)^{n+1}}{a\\left(n+1\\right)} + C \\quad \\left(n \\ne -1\\right)", explanation: "For an integrand whose only \\(x\\)-dependence is a linear bracket raised to a power, integrate as if the argument were \\(x\\) (giving \\(\\left(ax+b\\right)^{n+1}/\\left(n+1\\right)\\)), then divide by the inner coefficient \\(a\\) to undo the chain rule. The exclusion \\(n = -1\\) avoids dividing by \\(n+1 = 0\\) — that case uses the log rule." }, { stepNumber: 2, description: "Identify \\(a = 3\\), \\(n = -3\\).", workingLatex: "a\\left(n+1\\right) = 3 \\cdot \\left(-2\\right) = -6", explanation: "" }, { stepNumber: 3, description: "Apply the formula.", workingLatex: "\\displaystyle\\int \\left(3x - 1\\right)^{-3}\\,dx = \\frac{\\left(3x - 1\\right)^{-2}}{-6} + C = -\\frac{1}{6\\left(3x - 1\\right)^2} + C", explanation: "" } ], finalAnswer: "\\(-\\frac{1}{6\\left(3x-1\\right)^2} + C\\)." } },
  { id: "y2in2-009", topicRef: "y2in2", topicTitle: "Integrating f(ax + b) 09", difficulty: "Standard", answerType: "expression", questionText: "Find \\( \\displaystyle\\int \\frac{1}{\\sqrt{4x + 1}} \\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["linear-inner", "root"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-inner-argument rule.", workingLatex: "\\displaystyle\\int \\left(ax + b\\right)^{n}\\,dx = \\frac{\\left(ax + b\\right)^{n+1}}{a\\left(n+1\\right)} + C \\quad \\left(n \\ne -1\\right)", explanation: "For an integrand whose only \\(x\\)-dependence is a linear bracket raised to a power, integrate as if the argument were \\(x\\) (giving \\(\\left(ax+b\\right)^{n+1}/\\left(n+1\\right)\\)), then divide by the inner coefficient \\(a\\) to undo the chain rule. The exclusion \\(n = -1\\) avoids dividing by \\(n+1 = 0\\) — that case uses the log rule." }, { stepNumber: 2, description: "Rewrite as a negative fractional power.", workingLatex: "\\frac{1}{\\sqrt{4x + 1}} = \\left(4x + 1\\right)^{-\\tfrac{1}{2}}", explanation: "" }, { stepNumber: 3, description: "Identify \\(a = 4\\), \\(n = -\\frac{1}{2}\\).", workingLatex: "a\\left(n+1\\right) = 4 \\cdot \\frac{1}{2} = 2", explanation: "" }, { stepNumber: 4, description: "Apply the formula.", workingLatex: "\\displaystyle\\int \\left(4x + 1\\right)^{-\\tfrac{1}{2}}\\,dx = \\frac{\\left(4x + 1\\right)^{\\tfrac{1}{2}}}{2} + C = \\frac{\\sqrt{4x + 1}}{2} + C", explanation: "" } ], finalAnswer: "\\(\\frac{\\sqrt{4x + 1}}{2} + C\\)." } },
  { id: "y2in2-010", topicRef: "y2in2", topicTitle: "Integrating f(ax + b) 10", difficulty: "Foundation", answerType: "expression", questionText: "Find \\( \\displaystyle\\int e^{3x + 2} \\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["linear-inner", "exp"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-inner-argument rule.", workingLatex: "\\displaystyle\\int e^{ax + b}\\,dx = \\frac{e^{ax + b}}{a} + C", explanation: "\\(\\frac{d}{dx}e^{ax+b} = ae^{ax+b}\\) by the chain rule; reading in reverse, the antiderivative needs a divide-by-\\(a\\) to cancel that factor." }, { stepNumber: 2, description: "Identify \\(a = 3\\).", workingLatex: "a = 3", explanation: "" }, { stepNumber: 3, description: "Apply the formula.", workingLatex: "\\displaystyle\\int e^{3x + 2}\\,dx = \\frac{e^{3x + 2}}{3} + C", explanation: "Check: \\(\\frac{d}{dx}\\frac{e^{3x+2}}{3} = \\frac{e^{3x+2} \\cdot 3}{3} = e^{3x+2}\\) ✓." } ], finalAnswer: "\\(\\frac{e^{3x + 2}}{3} + C\\)." } },
  { id: "y2in2-011", topicRef: "y2in2", topicTitle: "Integrating f(ax + b) 11", difficulty: "Standard", answerType: "expression", questionText: "Find \\( \\displaystyle\\int e^{1 - 2x} \\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["linear-inner", "exp"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-inner-argument rule.", workingLatex: "\\displaystyle\\int e^{ax + b}\\,dx = \\frac{e^{ax + b}}{a} + C", explanation: "\\(\\frac{d}{dx}e^{ax+b} = ae^{ax+b}\\) by the chain rule; reading in reverse, the antiderivative needs a divide-by-\\(a\\) to cancel that factor." }, { stepNumber: 2, description: "Identify \\(a = -2\\).", workingLatex: "1 - 2x = -2x + 1 \\;\\Rightarrow\\; a = -2", explanation: "The crucial \\(a\\) is the coefficient of \\(x\\), not the constant." }, { stepNumber: 3, description: "Apply the formula.", workingLatex: "\\displaystyle\\int e^{1 - 2x}\\,dx = \\frac{e^{1 - 2x}}{-2} + C = -\\frac{e^{1 - 2x}}{2} + C", explanation: "" } ], finalAnswer: "\\(-\\frac{e^{1 - 2x}}{2} + C\\)." } },
  { id: "y2in2-012", topicRef: "y2in2", topicTitle: "Integrating f(ax + b) 12", difficulty: "Standard", answerType: "expression", questionText: "Find \\( \\displaystyle\\int e^{-x/2} \\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["linear-inner", "exp"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-inner-argument rule.", workingLatex: "\\displaystyle\\int e^{ax + b}\\,dx = \\frac{e^{ax + b}}{a} + C", explanation: "\\(\\frac{d}{dx}e^{ax+b} = ae^{ax+b}\\) by the chain rule; reading in reverse, the antiderivative needs a divide-by-\\(a\\) to cancel that factor." }, { stepNumber: 2, description: "Identify the inner coefficient \\(a = -\\frac{1}{2}\\).", workingLatex: "a = -\\frac{1}{2} \\;\\Rightarrow\\; \\frac{1}{a} = -2", explanation: "Dividing by a fraction means multiplying by its reciprocal." }, { stepNumber: 3, description: "Apply the formula.", workingLatex: "\\displaystyle\\int e^{-x/2}\\,dx = -2e^{-x/2} + C", explanation: "" } ], finalAnswer: "\\(-2e^{-x/2} + C\\)." } },
  { id: "y2in2-013", topicRef: "y2in2", topicTitle: "Integrating f(ax + b) 13", difficulty: "Standard", answerType: "expression", questionText: "Find \\( \\displaystyle\\int 5e^{4x - 1} \\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["linear-inner", "exp"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-inner-argument rule.", workingLatex: "\\displaystyle\\int e^{ax + b}\\,dx = \\frac{e^{ax + b}}{a} + C", explanation: "\\(\\frac{d}{dx}e^{ax+b} = ae^{ax+b}\\) by the chain rule; reading in reverse, the antiderivative needs a divide-by-\\(a\\) to cancel that factor." }, { stepNumber: 2, description: "Pull the constant out, identify \\(a = 4\\).", workingLatex: "\\displaystyle\\int 5e^{4x - 1}\\,dx = 5\\displaystyle\\int e^{4x - 1}\\,dx,\\quad a = 4", explanation: "" }, { stepNumber: 3, description: "Apply the formula and combine constants.", workingLatex: "= 5 \\cdot \\frac{e^{4x - 1}}{4} + C = \\frac{5}{4}e^{4x - 1} + C", explanation: "" } ], finalAnswer: "\\(\\frac{5}{4}e^{4x - 1} + C\\)." } },
  { id: "y2in2-014", topicRef: "y2in2", topicTitle: "Integrating f(ax + b) 14", difficulty: "Foundation", answerType: "expression", questionText: "Find \\( \\displaystyle\\int \\frac{1}{2x + 3} \\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["linear-inner", "log"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-inner-argument rule.", workingLatex: "\\displaystyle\\int \\frac{1}{ax + b}\\,dx = \\frac{1}{a}\\ln|ax + b| + C", explanation: "The \\(n = -1\\) case of the power rule: the reciprocal of a linear expression integrates to a log of its modulus, scaled by \\(\\frac{1}{a}\\). Keep the modulus signs so the antiderivative is valid for both signs of the argument." }, { stepNumber: 2, description: "Identify \\(a = 2\\).", workingLatex: "a = 2", explanation: "" }, { stepNumber: 3, description: "Apply the formula.", workingLatex: "\\displaystyle\\int \\frac{1}{2x + 3}\\,dx = \\frac{1}{2}\\ln|2x + 3| + C", explanation: "" } ], finalAnswer: "\\(\\frac{1}{2}\\ln|2x + 3| + C\\)." } },
  { id: "y2in2-015", topicRef: "y2in2", topicTitle: "Integrating f(ax + b) 15", difficulty: "Standard", answerType: "expression", questionText: "Find \\( \\displaystyle\\int \\frac{1}{3 - x} \\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["linear-inner", "log"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-inner-argument rule.", workingLatex: "\\displaystyle\\int \\frac{1}{ax + b}\\,dx = \\frac{1}{a}\\ln|ax + b| + C", explanation: "The \\(n = -1\\) case of the power rule: the reciprocal of a linear expression integrates to a log of its modulus, scaled by \\(\\frac{1}{a}\\). Keep the modulus signs so the antiderivative is valid for both signs of the argument." }, { stepNumber: 2, description: "Identify \\(a = -1\\).", workingLatex: "3 - x = -1 \\cdot x + 3 \\;\\Rightarrow\\; a = -1", explanation: "" }, { stepNumber: 3, description: "Apply the formula.", workingLatex: "\\displaystyle\\int \\frac{1}{3 - x}\\,dx = \\frac{1}{-1}\\ln|3 - x| + C = -\\ln|3 - x| + C", explanation: "" } ], finalAnswer: "\\(-\\ln|3 - x| + C\\)." } },
  { id: "y2in2-016", topicRef: "y2in2", topicTitle: "Integrating f(ax + b) 16", difficulty: "Standard", answerType: "expression", questionText: "Find \\( \\displaystyle\\int \\frac{4}{5x - 2} \\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["linear-inner", "log"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-inner-argument rule.", workingLatex: "\\displaystyle\\int \\frac{1}{ax + b}\\,dx = \\frac{1}{a}\\ln|ax + b| + C", explanation: "The \\(n = -1\\) case of the power rule: the reciprocal of a linear expression integrates to a log of its modulus, scaled by \\(\\frac{1}{a}\\). Keep the modulus signs so the antiderivative is valid for both signs of the argument." }, { stepNumber: 2, description: "Pull constant out, identify \\(a = 5\\).", workingLatex: "\\displaystyle\\int \\frac{4}{5x - 2}\\,dx = 4\\displaystyle\\int \\frac{1}{5x - 2}\\,dx", explanation: "" }, { stepNumber: 3, description: "Apply the formula.", workingLatex: "= 4 \\cdot \\frac{1}{5}\\ln|5x - 2| + C = \\frac{4}{5}\\ln|5x - 2| + C", explanation: "" } ], finalAnswer: "\\(\\frac{4}{5}\\ln|5x - 2| + C\\)." } },
  { id: "y2in2-017", topicRef: "y2in2", topicTitle: "Integrating f(ax + b) 17", difficulty: "Foundation", answerType: "expression", questionText: "Find \\( \\displaystyle\\int \\frac{3}{4x + 7} \\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["linear-inner", "log"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-inner-argument rule.", workingLatex: "\\displaystyle\\int \\frac{1}{ax + b}\\,dx = \\frac{1}{a}\\ln|ax + b| + C", explanation: "The \\(n = -1\\) case of the power rule: the reciprocal of a linear expression integrates to a log of its modulus, scaled by \\(\\frac{1}{a}\\). Keep the modulus signs so the antiderivative is valid for both signs of the argument." }, { stepNumber: 2, description: "Pull the \\(3\\) out, identify \\(a = 4\\).", workingLatex: "\\displaystyle\\int \\frac{3}{4x + 7}\\,dx = 3\\displaystyle\\int \\frac{1}{4x + 7}\\,dx,\\quad a = 4", explanation: "" }, { stepNumber: 3, description: "Apply the formula.", workingLatex: "= 3 \\cdot \\frac{1}{4}\\ln|4x + 7| + C = \\frac{3}{4}\\ln|4x + 7| + C", explanation: "" } ], finalAnswer: "\\(\\frac{3}{4}\\ln|4x + 7| + C\\)." } },
  { id: "y2in2-018", topicRef: "y2in2", topicTitle: "Integrating f(ax + b) 18", difficulty: "Foundation", answerType: "expression", questionText: "Find \\( \\displaystyle\\int \\sin\\left(3x\\right) \\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["linear-inner", "trig"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-inner-argument rule.", workingLatex: "\\displaystyle\\int \\sin\\left(ax + b\\right)\\,dx = -\\frac{\\cos\\left(ax + b\\right)}{a} + C", explanation: "Two things to remember: the leading minus from \\(\\int \\sin = -\\cos\\), and the divide-by-\\(a\\) from the chain rule." }, { stepNumber: 2, description: "Identify \\(a = 3\\).", workingLatex: "a = 3", explanation: "" }, { stepNumber: 3, description: "Apply the formula.", workingLatex: "\\displaystyle\\int \\sin\\left(3x\\right)\\,dx = -\\frac{\\cos\\left(3x\\right)}{3} + C", explanation: "Check: \\(\\frac{d}{dx}\\!\\left[-\\frac{\\cos 3x}{3}\\right] = -\\frac{-\\sin 3x \\cdot 3}{3} = \\sin 3x\\) ✓." } ], finalAnswer: "\\(-\\frac{\\cos 3x}{3} + C\\)." } },
  { id: "y2in2-019", topicRef: "y2in2", topicTitle: "Integrating f(ax + b) 19", difficulty: "Standard", answerType: "expression", questionText: "Find \\( \\displaystyle\\int \\cos\\left(2x - 1\\right) \\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["linear-inner", "trig"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-inner-argument rule.", workingLatex: "\\displaystyle\\int \\cos\\left(ax + b\\right)\\,dx = \\frac{\\sin\\left(ax + b\\right)}{a} + C", explanation: "No sign flip (unlike sine) — \\(\\int \\cos = +\\sin\\). Only the divide-by-\\(a\\) chain-rule correction." }, { stepNumber: 2, description: "Identify \\(a = 2\\) (the coefficient of \\(x\\)).", workingLatex: "a = 2", explanation: "" }, { stepNumber: 3, description: "Apply the formula.", workingLatex: "\\displaystyle\\int \\cos\\left(2x - 1\\right)\\,dx = \\frac{\\sin\\left(2x - 1\\right)}{2} + C", explanation: "" } ], finalAnswer: "\\(\\frac{\\sin\\left(2x - 1\\right)}{2} + C\\)." } },
  { id: "y2in2-020", topicRef: "y2in2", topicTitle: "Integrating f(ax + b) 20", difficulty: "Standard", answerType: "expression", questionText: "Find \\( \\displaystyle\\int 4\\sin\\left(\\pi x\\right) \\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["linear-inner", "trig"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-inner-argument rule.", workingLatex: "\\displaystyle\\int \\sin\\left(ax + b\\right)\\,dx = -\\frac{\\cos\\left(ax + b\\right)}{a} + C", explanation: "Two things to remember: the leading minus from \\(\\int \\sin = -\\cos\\), and the divide-by-\\(a\\) from the chain rule." }, { stepNumber: 2, description: "Pull the constant out, identify \\(a = \\pi\\).", workingLatex: "\\displaystyle\\int 4\\sin\\left(\\pi x\\right)\\,dx = 4\\displaystyle\\int \\sin\\left(\\pi x\\right)\\,dx,\\quad a = \\pi", explanation: "\\(\\pi\\) is a numerical constant — it plays the same role as any other \\(a\\)." }, { stepNumber: 3, description: "Apply the formula.", workingLatex: "= 4 \\cdot \\left(-\\frac{\\cos \\pi x}{\\pi}\\right) + C = -\\frac{4\\cos \\pi x}{\\pi} + C", explanation: "" } ], finalAnswer: "\\(-\\frac{4\\cos\\pi x}{\\pi} + C\\)." } },
  { id: "y2in2-021", topicRef: "y2in2", topicTitle: "Integrating f(ax + b) 21", difficulty: "Standard", answerType: "expression", questionText: "Find \\( \\displaystyle\\int \\cos\\left(5 - x\\right) \\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["linear-inner", "trig"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-inner-argument rule.", workingLatex: "\\displaystyle\\int \\cos\\left(ax + b\\right)\\,dx = \\frac{\\sin\\left(ax + b\\right)}{a} + C", explanation: "No sign flip (unlike sine) — \\(\\int \\cos = +\\sin\\). Only the divide-by-\\(a\\) chain-rule correction." }, { stepNumber: 2, description: "Identify \\(a = -1\\).", workingLatex: "5 - x = -1 \\cdot x + 5 \\;\\Rightarrow\\; a = -1", explanation: "" }, { stepNumber: 3, description: "Apply the formula.", workingLatex: "\\displaystyle\\int \\cos\\left(5 - x\\right)\\,dx = \\frac{\\sin\\left(5 - x\\right)}{-1} + C = -\\sin\\left(5 - x\\right) + C", explanation: "" } ], finalAnswer: "\\(-\\sin\\left(5 - x\\right) + C\\)." } },
  { id: "y2in2-022", topicRef: "y2in2", topicTitle: "Integrating f(ax + b) 22", difficulty: "Standard", answerType: "expression", questionText: "Find \\( \\displaystyle\\int \\sec^2\\left(4x\\right) \\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["linear-inner", "trig"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-inner-argument rule.", workingLatex: "\\displaystyle\\int \\sec^{2}\\left(ax + b\\right)\\,dx = \\frac{\\tan\\left(ax + b\\right)}{a} + C", explanation: "Base antiderivative: \\(\\int \\sec^2 x\\,dx = \\tan x\\). Apply the linear-inner-argument divide-by-\\(a\\)." }, { stepNumber: 2, description: "Identify \\(a = 4\\).", workingLatex: "a = 4", explanation: "" }, { stepNumber: 3, description: "Apply the formula.", workingLatex: "\\displaystyle\\int \\sec^2\\left(4x\\right)\\,dx = \\frac{\\tan 4x}{4} + C", explanation: "" } ], finalAnswer: "\\(\\frac{\\tan 4x}{4} + C\\)." } },
  { id: "y2in2-023", topicRef: "y2in2", topicTitle: "Integrating f(ax + b) 23", difficulty: "Standard", answerType: "expression", questionText: "Find \\( \\displaystyle\\int \\csc^2\\left(2x - 1\\right) \\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["linear-inner", "trig"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-inner-argument rule.", workingLatex: "\\displaystyle\\int \\csc^{2}\\left(ax + b\\right)\\,dx = -\\frac{\\cot\\left(ax + b\\right)}{a} + C", explanation: "Base: \\(\\int \\csc^2 x\\,dx = -\\cot x\\) (mind the minus). Then divide by \\(a\\)." }, { stepNumber: 2, description: "Identify \\(a = 2\\).", workingLatex: "a = 2", explanation: "" }, { stepNumber: 3, description: "Apply the formula.", workingLatex: "\\displaystyle\\int \\csc^2\\left(2x - 1\\right)\\,dx = -\\frac{\\cot\\left(2x - 1\\right)}{2} + C", explanation: "" } ], finalAnswer: "\\(-\\frac{\\cot\\left(2x - 1\\right)}{2} + C\\)." } },
  { id: "y2in2-024", topicRef: "y2in2", topicTitle: "Integrating f(ax + b) 24", difficulty: "Standard", answerType: "expression", questionText: "Find \\( \\displaystyle\\int \\sec\\left(3x\\right)\\tan\\left(3x\\right) \\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["linear-inner", "trig"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-inner-argument rule.", workingLatex: "\\displaystyle\\int \\sec\\left(ax + b\\right)\\tan\\left(ax + b\\right)\\,dx = \\frac{\\sec\\left(ax + b\\right)}{a} + C", explanation: "Base: \\(\\int \\sec x\\tan x\\,dx = \\sec x\\). Divide by \\(a\\)." }, { stepNumber: 2, description: "Identify \\(a = 3\\).", workingLatex: "a = 3", explanation: "" }, { stepNumber: 3, description: "Apply the formula.", workingLatex: "\\displaystyle\\int \\sec\\left(3x\\right)\\tan\\left(3x\\right)\\,dx = \\frac{\\sec 3x}{3} + C", explanation: "" } ], finalAnswer: "\\(\\frac{\\sec 3x}{3} + C\\)." } },
  { id: "y2in2-025", topicRef: "y2in2", topicTitle: "Integrating f(ax + b) 25", difficulty: "Standard", answerType: "expression", questionText: "Find \\( \\displaystyle\\int \\csc\\left(5x\\right)\\cot\\left(5x\\right) \\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["linear-inner", "trig"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-inner-argument rule.", workingLatex: "\\displaystyle\\int \\csc\\left(ax + b\\right)\\cot\\left(ax + b\\right)\\,dx = -\\frac{\\csc\\left(ax + b\\right)}{a} + C", explanation: "Base: \\(\\int \\csc x\\cot x\\,dx = -\\csc x\\) (mind the minus). Divide by \\(a\\)." }, { stepNumber: 2, description: "Identify \\(a = 5\\).", workingLatex: "a = 5", explanation: "" }, { stepNumber: 3, description: "Apply the formula.", workingLatex: "\\displaystyle\\int \\csc\\left(5x\\right)\\cot\\left(5x\\right)\\,dx = -\\frac{\\csc 5x}{5} + C", explanation: "" } ], finalAnswer: "\\(-\\frac{\\csc 5x}{5} + C\\)." } },
  { id: "y2in2-026", topicRef: "y2in2", topicTitle: "Integrating f(ax + b) 26", difficulty: "Standard", answerType: "expression", questionText: "Find \\( \\displaystyle\\int \\left(2\\sin 2x - 3\\cos 3x\\right) \\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["linear-inner", "trig"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-inner-argument rules we will need.", workingLatex: "\\displaystyle\\int \\sin\\left(ax + b\\right)\\,dx = -\\frac{\\cos\\left(ax + b\\right)}{a} + C \\\\\\\\[2pt] \\displaystyle\\int \\cos\\left(ax + b\\right)\\,dx = \\frac{\\sin\\left(ax + b\\right)}{a} + C", explanation: "Two things to remember: the leading minus from \\(\\int \\sin = -\\cos\\), and the divide-by-\\(a\\) from the chain rule.  No sign flip (unlike sine) — \\(\\int \\cos = +\\sin\\). Only the divide-by-\\(a\\) chain-rule correction." }, { stepNumber: 2, description: "Split term-by-term, pull constants out.", workingLatex: "\\displaystyle\\int \\left(2\\sin 2x - 3\\cos 3x\\right)\\,dx = 2\\displaystyle\\int \\sin 2x\\,dx - 3\\displaystyle\\int \\cos 3x\\,dx", explanation: "" }, { stepNumber: 3, description: "Apply the two formulas.", workingLatex: "= 2 \\cdot \\left(-\\frac{\\cos 2x}{2}\\right) - 3 \\cdot \\frac{\\sin 3x}{3} + C", explanation: "For \\(\\int \\sin 2x\\,dx\\): \\(a = 2\\); for \\(\\int \\cos 3x\\,dx\\): \\(a = 3\\)." }, { stepNumber: 4, description: "Simplify.", workingLatex: "= -\\cos 2x - \\sin 3x + C", explanation: "Both \\(2\\)s cancel; both \\(3\\)s cancel." } ], finalAnswer: "\\(-\\cos 2x - \\sin 3x + C\\)." } },
  { id: "y2in2-027", topicRef: "y2in2", topicTitle: "Integrating f(ax + b) 27", difficulty: "Standard", answerType: "expression", questionText: "Find \\( \\displaystyle\\int \\frac{1}{\\cos^2\\left(5x\\right)} \\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["linear-inner", "trig"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-inner-argument rule.", workingLatex: "\\displaystyle\\int \\sec^{2}\\left(ax + b\\right)\\,dx = \\frac{\\tan\\left(ax + b\\right)}{a} + C", explanation: "Base antiderivative: \\(\\int \\sec^2 x\\,dx = \\tan x\\). Apply the linear-inner-argument divide-by-\\(a\\)." }, { stepNumber: 2, description: "Rewrite using \\(\\sec^2\\).", workingLatex: "\\frac{1}{\\cos^2 5x} = \\sec^2 5x", explanation: "\\(\\sec = 1/\\cos\\), so \\(\\sec^2 = 1/\\cos^2\\) — reduces to the secant-squared rule." }, { stepNumber: 3, description: "Apply the formula with \\(a = 5\\).", workingLatex: "\\displaystyle\\int \\sec^2 5x\\,dx = \\frac{\\tan 5x}{5} + C", explanation: "" } ], finalAnswer: "\\(\\frac{\\tan 5x}{5} + C\\)." } },
  { id: "y2in2-028", topicRef: "y2in2", topicTitle: "Integrating f(ax + b) 28", difficulty: "Standard", answerType: "expression", questionText: "Evaluate \\( \\displaystyle\\int_0^1 \\left(2x + 1\\right)^2 \\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["definite", "linear-inner", "power"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-inner-argument rule.", workingLatex: "\\displaystyle\\int \\left(ax + b\\right)^{n}\\,dx = \\frac{\\left(ax + b\\right)^{n+1}}{a\\left(n+1\\right)} + C \\quad \\left(n \\ne -1\\right)", explanation: "For an integrand whose only \\(x\\)-dependence is a linear bracket raised to a power, integrate as if the argument were \\(x\\) (giving \\(\\left(ax+b\\right)^{n+1}/\\left(n+1\\right)\\)), then divide by the inner coefficient \\(a\\) to undo the chain rule. The exclusion \\(n = -1\\) avoids dividing by \\(n+1 = 0\\) — that case uses the log rule." }, { stepNumber: 2, description: "Find the antiderivative using the rule (\\(a = 2, n = 2\\)).", workingLatex: "\\displaystyle\\int \\left(2x + 1\\right)^2\\,dx = \\frac{\\left(2x + 1\\right)^3}{6}", explanation: "\\(a\\left(n+1\\right) = 6\\). Drop the \\(+C\\) since it cancels in a definite integral." }, { stepNumber: 3, description: "Apply the limits.", workingLatex: "\\left[\\frac{\\left(2x + 1\\right)^3}{6}\\right]_0^1 = \\frac{27}{6} - \\frac{1}{6} = \\frac{26}{6}", explanation: "At \\(x = 1\\): \\(3\\); at \\(x = 0\\): \\(1\\)." }, { stepNumber: 4, description: "Simplify.", workingLatex: "= \\frac{13}{3}", explanation: "" } ], finalAnswer: "\\(\\frac{13}{3}\\)." } },
  { id: "y2in2-029", topicRef: "y2in2", topicTitle: "Integrating f(ax + b) 29", difficulty: "Standard", answerType: "expression", questionText: "Evaluate \\( \\displaystyle\\int_0^{\\pi/2} \\sin\\left(2x\\right) \\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["definite", "linear-inner", "trig"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-inner-argument rule.", workingLatex: "\\displaystyle\\int \\sin\\left(ax + b\\right)\\,dx = -\\frac{\\cos\\left(ax + b\\right)}{a} + C", explanation: "Two things to remember: the leading minus from \\(\\int \\sin = -\\cos\\), and the divide-by-\\(a\\) from the chain rule." }, { stepNumber: 2, description: "Find the antiderivative using the rule (\\(a = 2\\)).", workingLatex: "\\displaystyle\\int \\sin\\left(2x\\right)\\,dx = -\\frac{\\cos 2x}{2}", explanation: "" }, { stepNumber: 3, description: "Apply the limits.", workingLatex: "\\left[-\\frac{\\cos 2x}{2}\\right]_0^{\\pi/2} = -\\frac{\\cos \\pi}{2} + \\frac{\\cos 0}{2}", explanation: "" }, { stepNumber: 4, description: "Evaluate the cosines.", workingLatex: "= -\\frac{-1}{2} + \\frac{1}{2} = 1", explanation: "" } ], finalAnswer: "1." } },
  { id: "y2in2-030", topicRef: "y2in2", topicTitle: "Integrating f(ax + b) 30", difficulty: "Standard", answerType: "expression", questionText: "Evaluate \\( \\displaystyle\\int_0^2 e^{3x} \\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["definite", "linear-inner", "exp"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-inner-argument rule.", workingLatex: "\\displaystyle\\int e^{ax + b}\\,dx = \\frac{e^{ax + b}}{a} + C", explanation: "\\(\\frac{d}{dx}e^{ax+b} = ae^{ax+b}\\) by the chain rule; reading in reverse, the antiderivative needs a divide-by-\\(a\\) to cancel that factor." }, { stepNumber: 2, description: "Find the antiderivative using the rule (\\(a = 3\\)).", workingLatex: "\\displaystyle\\int e^{3x}\\,dx = \\frac{e^{3x}}{3}", explanation: "" }, { stepNumber: 3, description: "Apply the limits.", workingLatex: "\\left[\\frac{e^{3x}}{3}\\right]_0^2 = \\frac{e^6}{3} - \\frac{1}{3} = \\frac{e^6 - 1}{3}", explanation: "" } ], finalAnswer: "\\(\\frac{e^6 - 1}{3}\\)." } },
  { id: "y2in2-031", topicRef: "y2in2", topicTitle: "Integrating f(ax + b) 31", difficulty: "Standard", answerType: "expression", questionText: "Evaluate \\( \\displaystyle\\int_1^3 \\frac{1}{2x + 1} \\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["definite", "linear-inner", "log"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-inner-argument rule.", workingLatex: "\\displaystyle\\int \\frac{1}{ax + b}\\,dx = \\frac{1}{a}\\ln|ax + b| + C", explanation: "The \\(n = -1\\) case of the power rule: the reciprocal of a linear expression integrates to a log of its modulus, scaled by \\(\\frac{1}{a}\\). Keep the modulus signs so the antiderivative is valid for both signs of the argument." }, { stepNumber: 2, description: "Find the antiderivative using the rule (\\(a = 2\\)).", workingLatex: "\\displaystyle\\int \\frac{1}{2x + 1}\\,dx = \\frac{1}{2}\\ln|2x + 1|", explanation: "" }, { stepNumber: 3, description: "Apply the limits.", workingLatex: "\\left[\\frac{1}{2}\\ln|2x + 1|\\right]_1^3 = \\frac{1}{2}\\ln 7 - \\frac{1}{2}\\ln 3", explanation: "" }, { stepNumber: 4, description: "Combine with \\(\\ln a - \\ln b = \\ln(a/b)\\).", workingLatex: "= \\frac{1}{2}\\ln\\frac{7}{3}", explanation: "" } ], finalAnswer: "\\(\\frac{1}{2}\\ln\\frac{7}{3}\\)." } },
  { id: "y2in2-032", topicRef: "y2in2", topicTitle: "Integrating f(ax + b) 32", difficulty: "Standard", answerType: "expression", questionText: "Evaluate \\( \\displaystyle\\int_0^{\\pi/4} \\sec^2\\left(2x\\right) \\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["definite", "improper", "linear-inner", "trig"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-inner-argument rule.", workingLatex: "\\displaystyle\\int \\sec^{2}\\left(ax + b\\right)\\,dx = \\frac{\\tan\\left(ax + b\\right)}{a} + C", explanation: "Base antiderivative: \\(\\int \\sec^2 x\\,dx = \\tan x\\). Apply the linear-inner-argument divide-by-\\(a\\)." }, { stepNumber: 2, description: "Find the antiderivative using the rule (\\(a = 2\\)).", workingLatex: "\\displaystyle\\int \\sec^2 2x\\,dx = \\frac{\\tan 2x}{2}", explanation: "" }, { stepNumber: 3, description: "Check the antiderivative is defined throughout \\([0, \\pi/4]\\).", workingLatex: "\\text{At } x = \\frac{\\pi}{4}:\\; 2x = \\frac{\\pi}{2},\\;\\; \\tan\\!\\frac{\\pi}{2} \\text{ is undefined}", explanation: "\\(\\tan\\) has a vertical asymptote at \\(\\pi/2\\) — exactly the upper limit. Always check the antiderivative is defined at every point of the interval before plugging in limits." }, { stepNumber: 4, description: "Interpret as improper and evaluate the limit.", workingLatex: "\\displaystyle\\int_0^{\\pi/4} \\sec^2 2x\\,dx = \\lim_{b \\to \\left(\\pi/4\\right)^-} \\frac{\\tan 2b}{2} - 0 = +\\infty", explanation: "As \\(b \\to \\left(\\pi/4\\right)^-\\), \\(\\tan 2b \\to +\\infty\\), so the limit diverges." } ], finalAnswer: "Diverges (improper at the upper limit: \\(\\tan 2x \\to \\infty\\) as \\(x \\to \\left(\\pi/4\\right)^-\\))." } },
  { id: "y2in2-033", topicRef: "y2in2", topicTitle: "Integrating f(ax + b) 33", difficulty: "Standard", answerType: "expression", questionText: "Evaluate \\( \\displaystyle\\int_0^{\\pi/6} \\cos\\left(3x\\right) \\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["definite", "linear-inner", "trig"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-inner-argument rule.", workingLatex: "\\displaystyle\\int \\cos\\left(ax + b\\right)\\,dx = \\frac{\\sin\\left(ax + b\\right)}{a} + C", explanation: "No sign flip (unlike sine) — \\(\\int \\cos = +\\sin\\). Only the divide-by-\\(a\\) chain-rule correction." }, { stepNumber: 2, description: "Find the antiderivative using the rule (\\(a = 3\\)).", workingLatex: "\\displaystyle\\int \\cos\\left(3x\\right)\\,dx = \\frac{\\sin 3x}{3}", explanation: "" }, { stepNumber: 3, description: "Apply the limits.", workingLatex: "\\left[\\frac{\\sin 3x}{3}\\right]_0^{\\pi/6} = \\frac{1}{3} - 0 = \\frac{1}{3}", explanation: "\\(\\sin\\left(\\pi/2\\right) = 1\\); \\(\\sin 0 = 0\\)." } ], finalAnswer: "\\(\\frac{1}{3}\\)." } },
  { id: "y2in2-034", topicRef: "y2in2", topicTitle: "Integrating f(ax + b) 34", difficulty: "Standard", answerType: "expression", questionText: "Evaluate \\( \\displaystyle\\int_1^4 \\sqrt{2x - 1} \\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["definite", "linear-inner", "root"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-inner-argument rule.", workingLatex: "\\displaystyle\\int \\left(ax + b\\right)^{n}\\,dx = \\frac{\\left(ax + b\\right)^{n+1}}{a\\left(n+1\\right)} + C \\quad \\left(n \\ne -1\\right)", explanation: "For an integrand whose only \\(x\\)-dependence is a linear bracket raised to a power, integrate as if the argument were \\(x\\) (giving \\(\\left(ax+b\\right)^{n+1}/\\left(n+1\\right)\\)), then divide by the inner coefficient \\(a\\) to undo the chain rule. The exclusion \\(n = -1\\) avoids dividing by \\(n+1 = 0\\) — that case uses the log rule." }, { stepNumber: 2, description: "Find the antiderivative using the rule (\\(a = 2, n = \\frac{1}{2}\\)).", workingLatex: "\\displaystyle\\int \\left(2x - 1\\right)^{\\tfrac{1}{2}}\\,dx = \\frac{\\left(2x - 1\\right)^{\\tfrac{3}{2}}}{3}", explanation: "\\(a\\left(n+1\\right) = 3\\)." }, { stepNumber: 3, description: "Apply the limits.", workingLatex: "\\left[\\frac{\\left(2x - 1\\right)^{\\tfrac{3}{2}}}{3}\\right]_1^4 = \\frac{7^{\\tfrac{3}{2}}}{3} - \\frac{1^{\\tfrac{3}{2}}}{3} = \\frac{7\\sqrt 7 - 1}{3}", explanation: "\\(7^{3/2} = 7\\sqrt 7\\); \\(1^{3/2} = 1\\)." } ], finalAnswer: "\\(\\frac{7\\sqrt 7 - 1}{3}\\)." } },
  { id: "y2in2-035", topicRef: "y2in2", topicTitle: "Integrating f(ax + b) 35", difficulty: "Standard", answerType: "expression", questionText: "Evaluate \\( \\displaystyle\\int_0^{\\ln 2} e^{-x} \\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["definite", "linear-inner", "exp"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-inner-argument rule.", workingLatex: "\\displaystyle\\int e^{ax + b}\\,dx = \\frac{e^{ax + b}}{a} + C", explanation: "\\(\\frac{d}{dx}e^{ax+b} = ae^{ax+b}\\) by the chain rule; reading in reverse, the antiderivative needs a divide-by-\\(a\\) to cancel that factor." }, { stepNumber: 2, description: "Find the antiderivative using the rule (\\(a = -1\\)).", workingLatex: "\\displaystyle\\int e^{-x}\\,dx = -e^{-x}", explanation: "" }, { stepNumber: 3, description: "Apply the limits.", workingLatex: "\\left[-e^{-x}\\right]_0^{\\ln 2} = -\\frac{1}{2} + 1 = \\frac{1}{2}", explanation: "\\(e^{-\\ln 2} = 1/2\\); \\(e^0 = 1\\)." } ], finalAnswer: "\\(\\frac{1}{2}\\)." } },
  { id: "y2in2-036", topicRef: "y2in2", topicTitle: "Integrating f(ax + b) 36", difficulty: "Standard", answerType: "expression", questionText: "Find \\( \\displaystyle\\int \\frac{5}{1 - 3x} \\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["linear-inner", "log"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-inner-argument rule.", workingLatex: "\\displaystyle\\int \\frac{1}{ax + b}\\,dx = \\frac{1}{a}\\ln|ax + b| + C", explanation: "The \\(n = -1\\) case of the power rule: the reciprocal of a linear expression integrates to a log of its modulus, scaled by \\(\\frac{1}{a}\\). Keep the modulus signs so the antiderivative is valid for both signs of the argument." }, { stepNumber: 2, description: "Identify \\(a = -3\\), pull \\(5\\) out.", workingLatex: "\\displaystyle\\int \\frac{5}{1 - 3x}\\,dx = 5\\displaystyle\\int \\frac{1}{1 - 3x}\\,dx,\\quad a = -3", explanation: "" }, { stepNumber: 3, description: "Apply the formula.", workingLatex: "= 5 \\cdot \\frac{1}{-3}\\ln|1 - 3x| + C = -\\frac{5}{3}\\ln|1 - 3x| + C", explanation: "" } ], finalAnswer: "\\(-\\frac{5}{3}\\ln|1 - 3x| + C\\)." } },
  { id: "y2in2-037", topicRef: "y2in2", topicTitle: "Integrating f(ax + b) 37", difficulty: "Standard", answerType: "expression", questionText: "Find \\( \\displaystyle\\int \\left(7 - 2x\\right)^4 \\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["linear-inner", "power"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-inner-argument rule.", workingLatex: "\\displaystyle\\int \\left(ax + b\\right)^{n}\\,dx = \\frac{\\left(ax + b\\right)^{n+1}}{a\\left(n+1\\right)} + C \\quad \\left(n \\ne -1\\right)", explanation: "For an integrand whose only \\(x\\)-dependence is a linear bracket raised to a power, integrate as if the argument were \\(x\\) (giving \\(\\left(ax+b\\right)^{n+1}/\\left(n+1\\right)\\)), then divide by the inner coefficient \\(a\\) to undo the chain rule. The exclusion \\(n = -1\\) avoids dividing by \\(n+1 = 0\\) — that case uses the log rule." }, { stepNumber: 2, description: "Identify \\(a = -2\\), \\(n = 4\\).", workingLatex: "a\\left(n+1\\right) = -2 \\cdot 5 = -10", explanation: "" }, { stepNumber: 3, description: "Apply the formula.", workingLatex: "\\displaystyle\\int \\left(7 - 2x\\right)^4\\,dx = \\frac{\\left(7 - 2x\\right)^5}{-10} + C = -\\frac{\\left(7 - 2x\\right)^5}{10} + C", explanation: "" } ], finalAnswer: "\\(-\\frac{\\left(7-2x\\right)^5}{10} + C\\)." } },
  { id: "y2in2-038", topicRef: "y2in2", topicTitle: "Integrating f(ax + b) 38", difficulty: "Standard", answerType: "expression", questionText: "Find \\( \\displaystyle\\int e^{x/3 + 1} \\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["linear-inner", "exp"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-inner-argument rule.", workingLatex: "\\displaystyle\\int e^{ax + b}\\,dx = \\frac{e^{ax + b}}{a} + C", explanation: "\\(\\frac{d}{dx}e^{ax+b} = ae^{ax+b}\\) by the chain rule; reading in reverse, the antiderivative needs a divide-by-\\(a\\) to cancel that factor." }, { stepNumber: 2, description: "Identify \\(a = \\frac{1}{3}\\).", workingLatex: "\\frac{1}{a} = 3", explanation: "" }, { stepNumber: 3, description: "Apply the formula.", workingLatex: "\\displaystyle\\int e^{x/3 + 1}\\,dx = 3e^{x/3 + 1} + C", explanation: "" } ], finalAnswer: "\\(3e^{x/3 + 1} + C\\)." } },
  { id: "y2in2-039", topicRef: "y2in2", topicTitle: "Integrating f(ax + b) 39", difficulty: "Standard", answerType: "expression", questionText: "Find \\( \\displaystyle\\int \\sin\\left(\\pi x - \\frac{\\pi}{2}\\right) \\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["linear-inner", "trig"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-inner-argument rule.", workingLatex: "\\displaystyle\\int \\sin\\left(ax + b\\right)\\,dx = -\\frac{\\cos\\left(ax + b\\right)}{a} + C", explanation: "Two things to remember: the leading minus from \\(\\int \\sin = -\\cos\\), and the divide-by-\\(a\\) from the chain rule." }, { stepNumber: 2, description: "Identify \\(a = \\pi\\), \\(b = -\\frac{\\pi}{2}\\).", workingLatex: "a = \\pi", explanation: "The constant \\(b\\) inside plays no role in the formula — only \\(a\\) divides." }, { stepNumber: 3, description: "Apply the formula.", workingLatex: "\\displaystyle\\int \\sin\\left(\\pi x - \\frac{\\pi}{2}\\right)\\,dx = -\\frac{\\cos\\left(\\pi x - \\pi/2\\right)}{\\pi} + C", explanation: "" } ], finalAnswer: "\\(-\\frac{\\cos\\left(\\pi x - \\pi/2\\right)}{\\pi} + C\\)." } },
  { id: "y2in2-040", topicRef: "y2in2", topicTitle: "Integrating f(ax + b) 40", difficulty: "Challenge", answerType: "expression", questionText: "Find \\( \\displaystyle\\int \\frac{2}{\\left(1 + 4x\\right)^3} \\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["linear-inner", "power"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-inner-argument rule.", workingLatex: "\\displaystyle\\int \\left(ax + b\\right)^{n}\\,dx = \\frac{\\left(ax + b\\right)^{n+1}}{a\\left(n+1\\right)} + C \\quad \\left(n \\ne -1\\right)", explanation: "For an integrand whose only \\(x\\)-dependence is a linear bracket raised to a power, integrate as if the argument were \\(x\\) (giving \\(\\left(ax+b\\right)^{n+1}/\\left(n+1\\right)\\)), then divide by the inner coefficient \\(a\\) to undo the chain rule. The exclusion \\(n = -1\\) avoids dividing by \\(n+1 = 0\\) — that case uses the log rule." }, { stepNumber: 2, description: "Pull the constant out, rewrite as a negative power.", workingLatex: "\\displaystyle\\int \\frac{2}{\\left(1 + 4x\\right)^3}\\,dx = 2\\displaystyle\\int \\left(1 + 4x\\right)^{-3}\\,dx", explanation: "" }, { stepNumber: 3, description: "Identify \\(a = 4\\), \\(n = -3\\).", workingLatex: "a\\left(n+1\\right) = -8", explanation: "" }, { stepNumber: 4, description: "Apply the formula.", workingLatex: "= 2 \\cdot \\frac{\\left(1 + 4x\\right)^{-2}}{-8} + C = -\\frac{1}{4\\left(1 + 4x\\right)^2} + C", explanation: "" } ], finalAnswer: "\\(-\\frac{1}{4\\left(1+4x\\right)^2} + C\\)." } },
  { id: "y2in2-041", topicRef: "y2in2", topicTitle: "Integrating f(ax + b) 41", difficulty: "Standard", answerType: "expression", questionText: "Find \\( \\displaystyle\\int \\frac{6}{\\sqrt{3x + 1}} \\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["linear-inner", "root"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-inner-argument rule.", workingLatex: "\\displaystyle\\int \\left(ax + b\\right)^{n}\\,dx = \\frac{\\left(ax + b\\right)^{n+1}}{a\\left(n+1\\right)} + C \\quad \\left(n \\ne -1\\right)", explanation: "For an integrand whose only \\(x\\)-dependence is a linear bracket raised to a power, integrate as if the argument were \\(x\\) (giving \\(\\left(ax+b\\right)^{n+1}/\\left(n+1\\right)\\)), then divide by the inner coefficient \\(a\\) to undo the chain rule. The exclusion \\(n = -1\\) avoids dividing by \\(n+1 = 0\\) — that case uses the log rule." }, { stepNumber: 2, description: "Pull constant out, rewrite radical.", workingLatex: "\\displaystyle\\int \\frac{6}{\\sqrt{3x + 1}}\\,dx = 6\\displaystyle\\int \\left(3x + 1\\right)^{-\\tfrac{1}{2}}\\,dx", explanation: "" }, { stepNumber: 3, description: "Identify \\(a = 3\\), \\(n = -\\frac{1}{2}\\).", workingLatex: "a\\left(n+1\\right) = \\frac{3}{2}", explanation: "" }, { stepNumber: 4, description: "Apply the formula.", workingLatex: "= 6 \\cdot \\frac{\\left(3x + 1\\right)^{\\tfrac{1}{2}}}{3/2} + C = 6 \\cdot \\frac{2}{3}\\left(3x + 1\\right)^{\\tfrac{1}{2}} + C = 4\\sqrt{3x + 1} + C", explanation: "" } ], finalAnswer: "\\(4\\sqrt{3x + 1} + C\\)." } },
  { id: "y2in2-042", topicRef: "y2in2", topicTitle: "Integrating f(ax + b) 42", difficulty: "Standard", answerType: "expression", questionText: "Find \\( \\displaystyle\\int [\\sin 2x + \\cos 3x + e^{4x}] \\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["linear-inner", "sum"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-inner-argument rules we will need.", workingLatex: "\\displaystyle\\int \\sin\\left(ax + b\\right)\\,dx = -\\frac{\\cos\\left(ax + b\\right)}{a} + C \\\\\\\\[2pt] \\displaystyle\\int \\cos\\left(ax + b\\right)\\,dx = \\frac{\\sin\\left(ax + b\\right)}{a} + C \\\\\\\\[2pt] \\displaystyle\\int e^{ax + b}\\,dx = \\frac{e^{ax + b}}{a} + C", explanation: "Two things to remember: the leading minus from \\(\\int \\sin = -\\cos\\), and the divide-by-\\(a\\) from the chain rule.  No sign flip (unlike sine) — \\(\\int \\cos = +\\sin\\). Only the divide-by-\\(a\\) chain-rule correction.  \\(\\frac{d}{dx}e^{ax+b} = ae^{ax+b}\\) by the chain rule; reading in reverse, the antiderivative needs a divide-by-\\(a\\) to cancel that factor." }, { stepNumber: 2, description: "Split term-by-term.", workingLatex: "\\displaystyle\\int \\sin 2x\\,dx + \\displaystyle\\int \\cos 3x\\,dx + \\displaystyle\\int e^{4x}\\,dx", explanation: "" }, { stepNumber: 3, description: "Apply the three formulas.", workingLatex: "= -\\frac{\\cos 2x}{2} + \\frac{\\sin 3x}{3} + \\frac{e^{4x}}{4} + C", explanation: "Divide each by its inner coefficient \\(2, 3, 4\\)." } ], finalAnswer: "\\(-\\frac{\\cos 2x}{2} + \\frac{\\sin 3x}{3} + \\frac{e^{4x}}{4} + C\\)." } },
  { id: "y2in2-043", topicRef: "y2in2", topicTitle: "Integrating f(ax + b) 43", difficulty: "Standard", answerType: "expression", questionText: "Find \\( \\displaystyle\\int [\\frac{1}{2x - 5} + e^{3x}] \\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["linear-inner", "sum"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-inner-argument rules we will need.", workingLatex: "\\displaystyle\\int \\frac{1}{ax + b}\\,dx = \\frac{1}{a}\\ln|ax + b| + C \\\\\\\\[2pt] \\displaystyle\\int e^{ax + b}\\,dx = \\frac{e^{ax + b}}{a} + C", explanation: "The \\(n = -1\\) case of the power rule: the reciprocal of a linear expression integrates to a log of its modulus, scaled by \\(\\frac{1}{a}\\). Keep the modulus signs so the antiderivative is valid for both signs of the argument.  \\(\\frac{d}{dx}e^{ax+b} = ae^{ax+b}\\) by the chain rule; reading in reverse, the antiderivative needs a divide-by-\\(a\\) to cancel that factor." }, { stepNumber: 2, description: "Split term-by-term.", workingLatex: "\\displaystyle\\int \\frac{1}{2x - 5}\\,dx + \\displaystyle\\int e^{3x}\\,dx", explanation: "" }, { stepNumber: 3, description: "Apply the two formulas.", workingLatex: "= \\frac{1}{2}\\ln|2x - 5| + \\frac{e^{3x}}{3} + C", explanation: "\\(a = 2\\) for the log; \\(a = 3\\) for the exponential." } ], finalAnswer: "\\(\\frac{1}{2}\\ln|2x - 5| + \\frac{e^{3x}}{3} + C\\)." } },
  { id: "y2in2-044", topicRef: "y2in2", topicTitle: "Integrating f(ax + b) 44", difficulty: "Standard", answerType: "expression", questionText: "Find \\(y\\) given \\(\\frac{dy}{dx} = e^{2x}\\) and \\(y\\left(0\\right) = 1\\).", marks: 4, examStyle: false, yearCreated: 2026, tags: ["ivp", "linear-inner", "exp"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-inner-argument rule.", workingLatex: "\\displaystyle\\int e^{ax + b}\\,dx = \\frac{e^{ax + b}}{a} + C", explanation: "\\(\\frac{d}{dx}e^{ax+b} = ae^{ax+b}\\) by the chain rule; reading in reverse, the antiderivative needs a divide-by-\\(a\\) to cancel that factor." }, { stepNumber: 2, description: "Integrate using the rule (\\(a = 2\\)).", workingLatex: "y = \\displaystyle\\int e^{2x}\\,dx = \\frac{e^{2x}}{2} + C", explanation: "" }, { stepNumber: 3, description: "Substitute the initial condition \\(y(0) = 1\\).", workingLatex: "1 = \\frac{1}{2} + C", explanation: "" }, { stepNumber: 4, description: "Solve for \\(C\\).", workingLatex: "C = \\frac{1}{2}", explanation: "" }, { stepNumber: 5, description: "Write the particular solution.", workingLatex: "y = \\frac{e^{2x}}{2} + \\frac{1}{2} = \\frac{e^{2x} + 1}{2}", explanation: "" } ], finalAnswer: "\\(y = \\frac{e^{2x} + 1}{2}\\)." } },
  { id: "y2in2-045", topicRef: "y2in2", topicTitle: "Integrating f(ax + b) 45", difficulty: "Standard", answerType: "expression", questionText: "Find \\(y\\) given \\(\\frac{dy}{dx} = \\sin\\left(\\frac{x}{2}\\right)\\) and \\(y\\left(\\pi\\right) = 3\\).", marks: 4, examStyle: false, yearCreated: 2026, tags: ["ivp", "linear-inner", "trig"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-inner-argument rule.", workingLatex: "\\displaystyle\\int \\sin\\left(ax + b\\right)\\,dx = -\\frac{\\cos\\left(ax + b\\right)}{a} + C", explanation: "Two things to remember: the leading minus from \\(\\int \\sin = -\\cos\\), and the divide-by-\\(a\\) from the chain rule." }, { stepNumber: 2, description: "Integrate using the rule (\\(a = \\frac{1}{2}\\)).", workingLatex: "y = \\displaystyle\\int \\sin\\left(x/2\\right)\\,dx = -\\frac{\\cos\\left(x/2\\right)}{1/2} + C = -2\\cos\\left(x/2\\right) + C", explanation: "" }, { stepNumber: 3, description: "Substitute \\(y(\\pi) = 3\\).", workingLatex: "3 = -2\\cos\\left(\\pi/2\\right) + C = 0 + C = C", explanation: "" }, { stepNumber: 4, description: "Write the particular solution.", workingLatex: "y = 3 - 2\\cos\\left(x/2\\right)", explanation: "" } ], finalAnswer: "\\(y = 3 - 2\\cos\\left(x/2\\right)\\)." } },
  { id: "y2in2-046", topicRef: "y2in2", topicTitle: "Integrating f(ax + b) 46", difficulty: "Standard", answerType: "expression", questionText: "Find the area under \\(y = e^{2x}\\) from \\(x = 0\\) to \\(x = 1\\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["definite", "linear-inner", "exp", "area"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-inner-argument rule.", workingLatex: "\\displaystyle\\int e^{ax + b}\\,dx = \\frac{e^{ax + b}}{a} + C", explanation: "\\(\\frac{d}{dx}e^{ax+b} = ae^{ax+b}\\) by the chain rule; reading in reverse, the antiderivative needs a divide-by-\\(a\\) to cancel that factor." }, { stepNumber: 2, description: "Set up the area as a definite integral.", workingLatex: "\\text{Area} = \\displaystyle\\int_0^1 e^{2x}\\,dx", explanation: "\\(e^{2x} > 0\\), so the integral gives the unsigned area." }, { stepNumber: 3, description: "Integrate using the rule (\\(a = 2\\)) and apply the limits.", workingLatex: "\\left[\\frac{e^{2x}}{2}\\right]_0^1 = \\frac{e^2 - 1}{2}", explanation: "" } ], finalAnswer: "\\(\\frac{e^2 - 1}{2}\\)." } },
  { id: "y2in2-047", topicRef: "y2in2", topicTitle: "Integrating f(ax + b) 47", difficulty: "Standard", answerType: "expression", questionText: "Find the area under \\(y = \\sin\\left(2x\\right)\\) from 0 to \\(\\pi/2\\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["definite", "linear-inner", "trig", "area"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-inner-argument rule.", workingLatex: "\\displaystyle\\int \\sin\\left(ax + b\\right)\\,dx = -\\frac{\\cos\\left(ax + b\\right)}{a} + C", explanation: "Two things to remember: the leading minus from \\(\\int \\sin = -\\cos\\), and the divide-by-\\(a\\) from the chain rule." }, { stepNumber: 2, description: "Set up the area.", workingLatex: "\\text{Area} = \\displaystyle\\int_0^{\\pi/2} \\sin\\left(2x\\right)\\,dx", explanation: "\\(\\sin 2x \\ge 0\\) on \\([0, \\pi/2]\\)." }, { stepNumber: 3, description: "Integrate using the rule (\\(a = 2\\)) and apply the limits.", workingLatex: "\\left[-\\frac{\\cos 2x}{2}\\right]_0^{\\pi/2} = \\frac{1}{2} + \\frac{1}{2} = 1", explanation: "" } ], finalAnswer: "1." } },
  { id: "y2in2-048", topicRef: "y2in2", topicTitle: "Integrating f(ax + b) 48", difficulty: "Standard", answerType: "expression", questionText: "Find the area under \\(y = \\frac{1}{2x + 1}\\) from 0 to 4.", marks: 3, examStyle: false, yearCreated: 2026, tags: ["definite", "linear-inner", "log", "area"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-inner-argument rule.", workingLatex: "\\displaystyle\\int \\frac{1}{ax + b}\\,dx = \\frac{1}{a}\\ln|ax + b| + C", explanation: "The \\(n = -1\\) case of the power rule: the reciprocal of a linear expression integrates to a log of its modulus, scaled by \\(\\frac{1}{a}\\). Keep the modulus signs so the antiderivative is valid for both signs of the argument." }, { stepNumber: 2, description: "Set up the area.", workingLatex: "\\text{Area} = \\displaystyle\\int_0^4 \\frac{1}{2x + 1}\\,dx", explanation: "" }, { stepNumber: 3, description: "Integrate using the rule (\\(a = 2\\)) and apply the limits.", workingLatex: "\\left[\\frac{1}{2}\\ln|2x + 1|\\right]_0^4 = \\frac{1}{2}\\ln 9 - 0 = \\frac{1}{2}\\ln 9", explanation: "" }, { stepNumber: 4, description: "Simplify using \\(\\ln 9 = 2\\ln 3\\).", workingLatex: "= \\ln 3", explanation: "" } ], finalAnswer: "\\(\\frac{1}{2}\\ln 9 = \\ln 3\\)." } },
  { id: "y2in2-049", topicRef: "y2in2", topicTitle: "Integrating f(ax + b) 49", difficulty: "Challenge", answerType: "expression", questionText: "A tank fills at rate \\(\\frac{dV}{dt} = 2e^{0.1t}\\). If \\(V\\left(0\\right) = 0\\), find \\(V\\left(t\\right)\\).", marks: 4, examStyle: false, yearCreated: 2026, tags: ["ivp", "linear-inner", "exp", "modelling"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-inner-argument rule.", workingLatex: "\\displaystyle\\int e^{ax + b}\\,dx = \\frac{e^{ax + b}}{a} + C", explanation: "\\(\\frac{d}{dx}e^{ax+b} = ae^{ax+b}\\) by the chain rule; reading in reverse, the antiderivative needs a divide-by-\\(a\\) to cancel that factor." }, { stepNumber: 2, description: "Integrate the rate using the rule (\\(a = 0.1\\)).", workingLatex: "V\\left(t\\right) = \\displaystyle\\int 2e^{0.1t}\\,dt = 2 \\cdot \\frac{e^{0.1t}}{0.1} + C = 20e^{0.1t} + C", explanation: "\\(\\frac{1}{a} = \\frac{1}{0.1} = 10\\); prefactor becomes \\(2 \\cdot 10 = 20\\)." }, { stepNumber: 3, description: "Apply \\(V(0) = 0\\).", workingLatex: "0 = 20 + C \\;\\Rightarrow\\; C = -20", explanation: "" }, { stepNumber: 4, description: "Write the particular solution.", workingLatex: "V\\left(t\\right) = 20\\left(e^{0.1t} - 1\\right)", explanation: "" } ], finalAnswer: "\\(V\\left(t\\right) = 20\\left(e^{0.1t} - 1\\right)\\)." } },
  { id: "y2in2-050", topicRef: "y2in2", topicTitle: "Integrating f(ax + b) 50", difficulty: "Challenge", answerType: "expression", questionText: "Velocity of a particle is \\(v = 3\\sin\\left(2t\\right)\\). Find displacement \\(s\\left(t\\right)\\) if \\(s\\left(0\\right) = 0\\).", marks: 4, examStyle: false, yearCreated: 2026, tags: ["ivp", "linear-inner", "trig", "kinematics"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-inner-argument rule.", workingLatex: "\\displaystyle\\int \\sin\\left(ax + b\\right)\\,dx = -\\frac{\\cos\\left(ax + b\\right)}{a} + C", explanation: "Two things to remember: the leading minus from \\(\\int \\sin = -\\cos\\), and the divide-by-\\(a\\) from the chain rule." }, { stepNumber: 2, description: "Recall \\(s(t) = \\int v\\,dt\\).", workingLatex: "s\\left(t\\right) = \\displaystyle\\int 3\\sin\\left(2t\\right)\\,dt", explanation: "" }, { stepNumber: 3, description: "Integrate using the rule (\\(a = 2\\)).", workingLatex: "s\\left(t\\right) = 3 \\cdot \\left(-\\frac{\\cos 2t}{2}\\right) + C = -\\frac{3}{2}\\cos 2t + C", explanation: "" }, { stepNumber: 4, description: "Apply \\(s(0) = 0\\).", workingLatex: "0 = -\\frac{3}{2} + C \\;\\Rightarrow\\; C = \\frac{3}{2}", explanation: "" }, { stepNumber: 5, description: "Write the displacement.", workingLatex: "s\\left(t\\right) = \\frac{3}{2}\\left(1 - \\cos 2t\\right)", explanation: "" } ], finalAnswer: "\\(s = \\frac{3}{2}\\left(1 - \\cos 2t\\right)\\)." } },
  { id: "y2in2-051", topicRef: "y2in2", topicTitle: "Integrating f(ax + b) 51", difficulty: "Foundation", answerType: "expression", questionText: "Find \\( \\displaystyle\\int \\left(1 - x\\right)^5 \\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["linear-inner", "power"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-inner-argument rule.", workingLatex: "\\displaystyle\\int \\left(ax + b\\right)^{n}\\,dx = \\frac{\\left(ax + b\\right)^{n+1}}{a\\left(n+1\\right)} + C \\quad \\left(n \\ne -1\\right)", explanation: "For an integrand whose only \\(x\\)-dependence is a linear bracket raised to a power, integrate as if the argument were \\(x\\) (giving \\(\\left(ax+b\\right)^{n+1}/\\left(n+1\\right)\\)), then divide by the inner coefficient \\(a\\) to undo the chain rule. The exclusion \\(n = -1\\) avoids dividing by \\(n+1 = 0\\) — that case uses the log rule." }, { stepNumber: 2, description: "Identify \\(a = -1\\), \\(n = 5\\).", workingLatex: "a\\left(n+1\\right) = -6", explanation: "" }, { stepNumber: 3, description: "Apply the formula.", workingLatex: "\\displaystyle\\int \\left(1 - x\\right)^5\\,dx = \\frac{\\left(1 - x\\right)^6}{-6} + C = -\\frac{\\left(1 - x\\right)^6}{6} + C", explanation: "" } ], finalAnswer: "\\(-\\frac{\\left(1 - x\\right)^6}{6} + C\\)." } },
  { id: "y2in2-052", topicRef: "y2in2", topicTitle: "Integrating f(ax + b) 52", difficulty: "Standard", answerType: "expression", questionText: "Find \\( \\displaystyle\\int \\left(2 - 3x\\right)^{-\\tfrac{1}{2}} \\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["linear-inner", "root"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-inner-argument rule.", workingLatex: "\\displaystyle\\int \\left(ax + b\\right)^{n}\\,dx = \\frac{\\left(ax + b\\right)^{n+1}}{a\\left(n+1\\right)} + C \\quad \\left(n \\ne -1\\right)", explanation: "For an integrand whose only \\(x\\)-dependence is a linear bracket raised to a power, integrate as if the argument were \\(x\\) (giving \\(\\left(ax+b\\right)^{n+1}/\\left(n+1\\right)\\)), then divide by the inner coefficient \\(a\\) to undo the chain rule. The exclusion \\(n = -1\\) avoids dividing by \\(n+1 = 0\\) — that case uses the log rule." }, { stepNumber: 2, description: "Identify \\(a = -3\\), \\(n = -\\frac{1}{2}\\).", workingLatex: "a\\left(n+1\\right) = -\\frac{3}{2}", explanation: "" }, { stepNumber: 3, description: "Apply the formula.", workingLatex: "\\displaystyle\\int \\left(2 - 3x\\right)^{-\\tfrac{1}{2}}\\,dx = \\frac{\\left(2 - 3x\\right)^{\\tfrac{1}{2}}}{-3/2} + C = -\\frac{2}{3}\\sqrt{2 - 3x} + C", explanation: "" } ], finalAnswer: "\\(-\\frac{2}{3}\\sqrt{2 - 3x} + C\\)." } },
  { id: "y2in2-053", topicRef: "y2in2", topicTitle: "Integrating f(ax + b) 53", difficulty: "Foundation", answerType: "expression", questionText: "Find \\( \\displaystyle\\int e^{ax} \\,dx \\) for \\(a \\ne 0\\).", marks: 1, examStyle: false, yearCreated: 2026, tags: ["linear-inner", "exp", "general"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-inner-argument rule.", workingLatex: "\\displaystyle\\int e^{ax + b}\\,dx = \\frac{e^{ax + b}}{a} + C", explanation: "\\(\\frac{d}{dx}e^{ax+b} = ae^{ax+b}\\) by the chain rule; reading in reverse, the antiderivative needs a divide-by-\\(a\\) to cancel that factor." }, { stepNumber: 2, description: "Derive: differentiate the proposed antiderivative.", workingLatex: "\\frac{d}{dx}\\!\\left(\\frac{e^{ax}}{a}\\right) = \\frac{a e^{ax}}{a} = e^{ax}", explanation: "Chain rule on \\(e^{ax}\\) brings down a factor of \\(a\\); dividing by \\(a\\) up front cancels it. So \\(\\frac{e^{ax}}{a}\\) is indeed an antiderivative." }, { stepNumber: 3, description: "Write the result.", workingLatex: "\\displaystyle\\int e^{ax}\\,dx = \\frac{e^{ax}}{a} + C", explanation: "The constraint \\(a \\ne 0\\) avoids dividing by zero. \\(a = 0\\) would just give \\(\\int 1\\,dx = x + C\\)." } ], finalAnswer: "\\(\\frac{e^{ax}}{a} + C\\)." } },
  { id: "y2in2-054", topicRef: "y2in2", topicTitle: "Integrating f(ax + b) 54", difficulty: "Foundation", answerType: "expression", questionText: "Find \\( \\displaystyle\\int \\sin\\left(ax + b\\right) \\,dx \\).", marks: 1, examStyle: false, yearCreated: 2026, tags: ["linear-inner", "trig", "general"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-inner-argument rule.", workingLatex: "\\displaystyle\\int \\sin\\left(ax + b\\right)\\,dx = -\\frac{\\cos\\left(ax + b\\right)}{a} + C", explanation: "Two things to remember: the leading minus from \\(\\int \\sin = -\\cos\\), and the divide-by-\\(a\\) from the chain rule." }, { stepNumber: 2, description: "Derive: differentiate the proposed antiderivative.", workingLatex: "\\frac{d}{dx}\\!\\left[-\\frac{\\cos\\left(ax + b\\right)}{a}\\right] = -\\frac{-\\sin\\left(ax + b\\right) \\cdot a}{a} = \\sin\\left(ax + b\\right)", explanation: "Chain rule: outer \\(\\frac{d}{du}\\left(-\\cos u\\right) = \\sin u\\); inner \\(u\\' = a\\). The divide-by-\\(a\\) cancels the chain factor." }, { stepNumber: 3, description: "Write the result.", workingLatex: "\\displaystyle\\int \\sin\\left(ax + b\\right)\\,dx = -\\frac{\\cos\\left(ax + b\\right)}{a} + C", explanation: "" } ], finalAnswer: "\\(-\\frac{\\cos\\left(ax + b\\right)}{a} + C\\)." } },
  { id: "y2in2-055", topicRef: "y2in2", topicTitle: "Integrating f(ax + b) 55", difficulty: "Foundation", answerType: "expression", questionText: "Find \\( \\displaystyle\\int \\cos\\left(ax + b\\right) \\,dx \\).", marks: 1, examStyle: false, yearCreated: 2026, tags: ["linear-inner", "trig", "general"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-inner-argument rule.", workingLatex: "\\displaystyle\\int \\cos\\left(ax + b\\right)\\,dx = \\frac{\\sin\\left(ax + b\\right)}{a} + C", explanation: "No sign flip (unlike sine) — \\(\\int \\cos = +\\sin\\). Only the divide-by-\\(a\\) chain-rule correction." }, { stepNumber: 2, description: "Derive: differentiate the proposed antiderivative.", workingLatex: "\\frac{d}{dx}\\!\\left[\\frac{\\sin\\left(ax + b\\right)}{a}\\right] = \\frac{\\cos\\left(ax + b\\right) \\cdot a}{a} = \\cos\\left(ax + b\\right)", explanation: "No sign flip (unlike sine)." }, { stepNumber: 3, description: "Write the result.", workingLatex: "\\displaystyle\\int \\cos\\left(ax + b\\right)\\,dx = \\frac{\\sin\\left(ax + b\\right)}{a} + C", explanation: "" } ], finalAnswer: "\\(\\frac{\\sin\\left(ax + b\\right)}{a} + C\\)." } },
  { id: "y2in2-056", topicRef: "y2in2", topicTitle: "Integrating f(ax + b) 56", difficulty: "Foundation", answerType: "expression", questionText: "Find \\( \\displaystyle\\int \\left(ax + b\\right)^n \\,dx \\) for \\(n \\ne -1\\).", marks: 1, examStyle: false, yearCreated: 2026, tags: ["linear-inner", "power", "general"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-inner-argument rule.", workingLatex: "\\displaystyle\\int \\left(ax + b\\right)^{n}\\,dx = \\frac{\\left(ax + b\\right)^{n+1}}{a\\left(n+1\\right)} + C \\quad \\left(n \\ne -1\\right)", explanation: "For an integrand whose only \\(x\\)-dependence is a linear bracket raised to a power, integrate as if the argument were \\(x\\) (giving \\(\\left(ax+b\\right)^{n+1}/\\left(n+1\\right)\\)), then divide by the inner coefficient \\(a\\) to undo the chain rule. The exclusion \\(n = -1\\) avoids dividing by \\(n+1 = 0\\) — that case uses the log rule." }, { stepNumber: 2, description: "Derive: differentiate the proposed antiderivative.", workingLatex: "\\frac{d}{dx}\\!\\left[\\frac{\\left(ax + b\\right)^{n+1}}{a\\left(n+1\\right)}\\right] = \\frac{\\left(n+1\\right)\\left(ax + b\\right)^{n} \\cdot a}{a\\left(n+1\\right)} = \\left(ax + b\\right)^{n}", explanation: "Chain rule brings down \\(a\\left(n+1\\right)\\); dividing by it up front cancels." }, { stepNumber: 3, description: "Write the result.", workingLatex: "\\displaystyle\\int \\left(ax + b\\right)^n\\,dx = \\frac{\\left(ax + b\\right)^{n+1}}{a\\left(n+1\\right)} + C", explanation: "Excludes \\(n = -1\\) — that case is the log rule (Q057)." } ], finalAnswer: "\\(\\frac{\\left(ax+b\\right)^{n+1}}{a\\left(n+1\\right)} + C\\)." } },
  { id: "y2in2-057", topicRef: "y2in2", topicTitle: "Integrating f(ax + b) 57", difficulty: "Foundation", answerType: "expression", questionText: "Find \\( \\displaystyle\\int \\frac{1}{ax + b} \\,dx \\).", marks: 1, examStyle: false, yearCreated: 2026, tags: ["linear-inner", "log", "general"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-inner-argument rule.", workingLatex: "\\displaystyle\\int \\frac{1}{ax + b}\\,dx = \\frac{1}{a}\\ln|ax + b| + C", explanation: "The \\(n = -1\\) case of the power rule: the reciprocal of a linear expression integrates to a log of its modulus, scaled by \\(\\frac{1}{a}\\). Keep the modulus signs so the antiderivative is valid for both signs of the argument." }, { stepNumber: 2, description: "Derive: differentiate the proposed antiderivative.", workingLatex: "\\frac{d}{dx}\\!\\left[\\frac{1}{a}\\ln|ax + b|\\right] = \\frac{1}{a} \\cdot \\frac{a}{ax + b} = \\frac{1}{ax + b}", explanation: "Chain rule on \\(\\ln|u|\\): outer \\(\\frac{1}{u}\\), inner \\(a\\). Modulus survives." }, { stepNumber: 3, description: "Write the result.", workingLatex: "\\displaystyle\\int \\frac{1}{ax + b}\\,dx = \\frac{1}{a}\\ln|ax + b| + C", explanation: "" } ], finalAnswer: "\\(\\frac{1}{a}\\ln|ax + b| + C\\)." } },
  { id: "y2in2-058", topicRef: "y2in2", topicTitle: "Integrating f(ax + b) 58", difficulty: "Standard", answerType: "expression", questionText: "Evaluate \\( \\displaystyle\\int_0^{\\ln 3} e^{-2x} \\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["definite", "linear-inner", "exp"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-inner-argument rule.", workingLatex: "\\displaystyle\\int e^{ax + b}\\,dx = \\frac{e^{ax + b}}{a} + C", explanation: "\\(\\frac{d}{dx}e^{ax+b} = ae^{ax+b}\\) by the chain rule; reading in reverse, the antiderivative needs a divide-by-\\(a\\) to cancel that factor." }, { stepNumber: 2, description: "Find the antiderivative using the rule (\\(a = -2\\)).", workingLatex: "\\displaystyle\\int e^{-2x}\\,dx = -\\frac{e^{-2x}}{2}", explanation: "" }, { stepNumber: 3, description: "Apply the limits.", workingLatex: "\\left[-\\frac{e^{-2x}}{2}\\right]_0^{\\ln 3} = -\\frac{e^{-2\\ln 3}}{2} + \\frac{1}{2}", explanation: "" }, { stepNumber: 4, description: "Simplify and combine.", workingLatex: "e^{-2\\ln 3} = \\frac{1}{9} \\;\\Rightarrow\\; -\\frac{1}{18} + \\frac{1}{2} = \\frac{4}{9}", explanation: "" } ], finalAnswer: "\\(\\frac{4}{9}\\)." } },
  { id: "y2in2-059", topicRef: "y2in2", topicTitle: "Integrating f(ax + b) 59", difficulty: "Standard", answerType: "expression", questionText: "Evaluate \\( \\displaystyle\\int_0^{\\pi/6} \\sin\\left(3x\\right) \\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["definite", "linear-inner", "trig"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-inner-argument rule.", workingLatex: "\\displaystyle\\int \\sin\\left(ax + b\\right)\\,dx = -\\frac{\\cos\\left(ax + b\\right)}{a} + C", explanation: "Two things to remember: the leading minus from \\(\\int \\sin = -\\cos\\), and the divide-by-\\(a\\) from the chain rule." }, { stepNumber: 2, description: "Find the antiderivative using the rule (\\(a = 3\\)).", workingLatex: "\\displaystyle\\int \\sin\\left(3x\\right)\\,dx = -\\frac{\\cos 3x}{3}", explanation: "" }, { stepNumber: 3, description: "Apply the limits.", workingLatex: "\\left[-\\frac{\\cos 3x}{3}\\right]_0^{\\pi/6} = 0 + \\frac{1}{3} = \\frac{1}{3}", explanation: "\\(\\cos\\left(\\pi/2\\right) = 0\\); \\(\\cos 0 = 1\\)." } ], finalAnswer: "\\(\\frac{1}{3}\\)." } },
  { id: "y2in2-060", topicRef: "y2in2", topicTitle: "Integrating f(ax + b) 60", difficulty: "Standard", answerType: "expression", questionText: "Evaluate \\( \\displaystyle\\int_0^1 \\left(3x + 2\\right)^3 \\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["definite", "linear-inner", "power"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-inner-argument rule.", workingLatex: "\\displaystyle\\int \\left(ax + b\\right)^{n}\\,dx = \\frac{\\left(ax + b\\right)^{n+1}}{a\\left(n+1\\right)} + C \\quad \\left(n \\ne -1\\right)", explanation: "For an integrand whose only \\(x\\)-dependence is a linear bracket raised to a power, integrate as if the argument were \\(x\\) (giving \\(\\left(ax+b\\right)^{n+1}/\\left(n+1\\right)\\)), then divide by the inner coefficient \\(a\\) to undo the chain rule. The exclusion \\(n = -1\\) avoids dividing by \\(n+1 = 0\\) — that case uses the log rule." }, { stepNumber: 2, description: "Find the antiderivative using the rule (\\(a = 3, n = 3\\)).", workingLatex: "\\displaystyle\\int \\left(3x + 2\\right)^3\\,dx = \\frac{\\left(3x + 2\\right)^4}{12}", explanation: "" }, { stepNumber: 3, description: "Apply the limits.", workingLatex: "\\left[\\frac{\\left(3x + 2\\right)^4}{12}\\right]_0^1 = \\frac{625 - 16}{12} = \\frac{609}{12}", explanation: "" }, { stepNumber: 4, description: "Decimal.", workingLatex: "= 50.75", explanation: "" } ], finalAnswer: "\\(\\frac{609}{12} = 50.75\\)." } },
  { id: "y2in2-061", topicRef: "y2in2", topicTitle: "Integrating f(ax + b) 61", difficulty: "Standard", answerType: "expression", questionText: "Evaluate \\( \\displaystyle\\int_0^2 \\frac{1}{\\left(x + 1\\right)^2} \\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["definite", "linear-inner", "power"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-inner-argument rule.", workingLatex: "\\displaystyle\\int \\left(ax + b\\right)^{n}\\,dx = \\frac{\\left(ax + b\\right)^{n+1}}{a\\left(n+1\\right)} + C \\quad \\left(n \\ne -1\\right)", explanation: "For an integrand whose only \\(x\\)-dependence is a linear bracket raised to a power, integrate as if the argument were \\(x\\) (giving \\(\\left(ax+b\\right)^{n+1}/\\left(n+1\\right)\\)), then divide by the inner coefficient \\(a\\) to undo the chain rule. The exclusion \\(n = -1\\) avoids dividing by \\(n+1 = 0\\) — that case uses the log rule." }, { stepNumber: 2, description: "Find the antiderivative using the rule (\\(a = 1, n = -2\\)).", workingLatex: "\\displaystyle\\int \\left(x + 1\\right)^{-2}\\,dx = \\frac{\\left(x + 1\\right)^{-1}}{-1} = -\\frac{1}{x + 1}", explanation: "" }, { stepNumber: 3, description: "Apply the limits.", workingLatex: "\\left[-\\frac{1}{x + 1}\\right]_0^2 = -\\frac{1}{3} + 1 = \\frac{2}{3}", explanation: "" } ], finalAnswer: "\\(\\frac{2}{3}\\)." } },
  { id: "y2in2-062", topicRef: "y2in2", topicTitle: "Integrating f(ax + b) 62", difficulty: "Challenge", answerType: "expression", questionText: "Evaluate \\( \\displaystyle\\int_0^{\\tfrac{1}{2}} \\sec^2\\left(\\pi x\\right) \\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["definite", "improper", "linear-inner", "trig"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-inner-argument rule.", workingLatex: "\\displaystyle\\int \\sec^{2}\\left(ax + b\\right)\\,dx = \\frac{\\tan\\left(ax + b\\right)}{a} + C", explanation: "Base antiderivative: \\(\\int \\sec^2 x\\,dx = \\tan x\\). Apply the linear-inner-argument divide-by-\\(a\\)." }, { stepNumber: 2, description: "Find the antiderivative using the rule (\\(a = \\pi\\)).", workingLatex: "\\displaystyle\\int \\sec^2 \\pi x\\,dx = \\frac{\\tan \\pi x}{\\pi}", explanation: "" }, { stepNumber: 3, description: "Check the antiderivative at the upper limit.", workingLatex: "\\text{At } x = \\frac{1}{2}:\\; \\pi x = \\frac{\\pi}{2},\\;\\; \\tan\\!\\frac{\\pi}{2} \\text{ undefined}", explanation: "Vertical asymptote exactly at the upper limit — improper integral." }, { stepNumber: 4, description: "Evaluate the limit.", workingLatex: "\\lim_{b \\to \\left(1/2\\right)^-} \\frac{\\tan \\pi b}{\\pi} - 0 = +\\infty", explanation: "" } ], finalAnswer: "Integral diverges (improper)." } },
  { id: "y2in2-063", topicRef: "y2in2", topicTitle: "Integrating f(ax + b) 63", difficulty: "Standard", answerType: "expression", questionText: "Evaluate \\( \\displaystyle\\int_0^{\\pi/12} \\sec^2\\left(2x\\right) \\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["definite", "linear-inner", "trig"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-inner-argument rule.", workingLatex: "\\displaystyle\\int \\sec^{2}\\left(ax + b\\right)\\,dx = \\frac{\\tan\\left(ax + b\\right)}{a} + C", explanation: "Base antiderivative: \\(\\int \\sec^2 x\\,dx = \\tan x\\). Apply the linear-inner-argument divide-by-\\(a\\)." }, { stepNumber: 2, description: "Find the antiderivative using the rule (\\(a = 2\\)).", workingLatex: "\\displaystyle\\int \\sec^2 2x\\,dx = \\frac{\\tan 2x}{2}", explanation: "" }, { stepNumber: 3, description: "Check the upper limit is in the antiderivative\\'s domain.", workingLatex: "\\text{At } x = \\frac{\\pi}{12}:\\; 2x = \\frac{\\pi}{6},\\;\\; \\tan\\!\\frac{\\pi}{6} = \\frac{1}{\\sqrt 3}\\; \\text{(finite)}", explanation: "Inside \\([0, \\pi/4)\\) — proper integral, unlike Q032/Q062." }, { stepNumber: 4, description: "Apply the limits and rationalise.", workingLatex: "\\left[\\frac{\\tan 2x}{2}\\right]_0^{\\pi/12} = \\frac{1}{2\\sqrt 3} = \\frac{\\sqrt 3}{6}", explanation: "" } ], finalAnswer: "\\(\\frac{1}{2\\sqrt 3} = \\frac{\\sqrt 3}{6}\\)." } },
  { id: "y2in2-064", topicRef: "y2in2", topicTitle: "Integrating f(ax + b) 64", difficulty: "Standard", answerType: "expression", questionText: "Evaluate \\( \\displaystyle\\int_{-1}^{2} \\left(2 - x\\right)^2 \\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["definite", "linear-inner", "power"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-inner-argument rule.", workingLatex: "\\displaystyle\\int \\left(ax + b\\right)^{n}\\,dx = \\frac{\\left(ax + b\\right)^{n+1}}{a\\left(n+1\\right)} + C \\quad \\left(n \\ne -1\\right)", explanation: "For an integrand whose only \\(x\\)-dependence is a linear bracket raised to a power, integrate as if the argument were \\(x\\) (giving \\(\\left(ax+b\\right)^{n+1}/\\left(n+1\\right)\\)), then divide by the inner coefficient \\(a\\) to undo the chain rule. The exclusion \\(n = -1\\) avoids dividing by \\(n+1 = 0\\) — that case uses the log rule." }, { stepNumber: 2, description: "Find the antiderivative using the rule (\\(a = -1, n = 2\\)).", workingLatex: "\\displaystyle\\int \\left(2 - x\\right)^2\\,dx = \\frac{\\left(2 - x\\right)^3}{-3} = -\\frac{\\left(2 - x\\right)^3}{3}", explanation: "" }, { stepNumber: 3, description: "Apply the limits.", workingLatex: "\\left[-\\frac{\\left(2 - x\\right)^3}{3}\\right]_{-1}^{2} = 0 + \\frac{27}{3} = 9", explanation: "" } ], finalAnswer: "9." } },
  { id: "y2in2-065", topicRef: "y2in2", topicTitle: "Integrating f(ax + b) 65", difficulty: "Standard", answerType: "expression", questionText: "Evaluate \\( \\displaystyle\\int_0^1 \\frac{6}{3x + 2} \\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["definite", "linear-inner", "log"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-inner-argument rule.", workingLatex: "\\displaystyle\\int \\frac{1}{ax + b}\\,dx = \\frac{1}{a}\\ln|ax + b| + C", explanation: "The \\(n = -1\\) case of the power rule: the reciprocal of a linear expression integrates to a log of its modulus, scaled by \\(\\frac{1}{a}\\). Keep the modulus signs so the antiderivative is valid for both signs of the argument." }, { stepNumber: 2, description: "Find the antiderivative using the rule (\\(a = 3\\)).", workingLatex: "\\displaystyle\\int \\frac{6}{3x + 2}\\,dx = 6 \\cdot \\frac{1}{3}\\ln|3x + 2| = 2\\ln|3x + 2|", explanation: "" }, { stepNumber: 3, description: "Apply the limits.", workingLatex: "\\left[2\\ln|3x + 2|\\right]_0^1 = 2\\ln 5 - 2\\ln 2 = 2\\ln\\frac{5}{2}", explanation: "" } ], finalAnswer: "\\(2\\ln\\frac{5}{2}\\)." } },
  { id: "y2in2-066", topicRef: "y2in2", topicTitle: "Integrating f(ax + b) 66", difficulty: "Challenge", answerType: "expression", questionText: "Evaluate \\( \\displaystyle\\int_0^{\\pi/2} \\cos\\left(2x\\right) \\,dx \\). Explain why this is 0.", marks: 3, examStyle: false, yearCreated: 2026, tags: ["definite", "linear-inner", "trig", "explain"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-inner-argument rule.", workingLatex: "\\displaystyle\\int \\cos\\left(ax + b\\right)\\,dx = \\frac{\\sin\\left(ax + b\\right)}{a} + C", explanation: "No sign flip (unlike sine) — \\(\\int \\cos = +\\sin\\). Only the divide-by-\\(a\\) chain-rule correction." }, { stepNumber: 2, description: "Find the antiderivative using the rule (\\(a = 2\\)).", workingLatex: "\\displaystyle\\int \\cos 2x\\,dx = \\frac{\\sin 2x}{2}", explanation: "" }, { stepNumber: 3, description: "Apply the limits.", workingLatex: "\\left[\\frac{\\sin 2x}{2}\\right]_0^{\\pi/2} = \\frac{\\sin \\pi - \\sin 0}{2} = 0", explanation: "" }, { stepNumber: 4, description: "Interpret geometrically.", workingLatex: "\\text{Equal positive and negative signed areas on } [0, \\pi/2]", explanation: "On \\([0, \\pi/4]\\) the integrand is positive; on \\([\\pi/4, \\pi/2]\\) it is negative. By symmetry the two regions cancel." } ], finalAnswer: "0." } },
  { id: "y2in2-067", topicRef: "y2in2", topicTitle: "Integrating f(ax + b) 67", difficulty: "Standard", answerType: "expression", questionText: "Find \\( \\displaystyle\\int [\\left(2x - 1\\right)^3 + e^{2x - 1}] \\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["linear-inner", "sum"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-inner-argument rules we will need.", workingLatex: "\\displaystyle\\int \\left(ax + b\\right)^{n}\\,dx = \\frac{\\left(ax + b\\right)^{n+1}}{a\\left(n+1\\right)} + C \\quad \\left(n \\ne -1\\right) \\\\\\\\[2pt] \\displaystyle\\int e^{ax + b}\\,dx = \\frac{e^{ax + b}}{a} + C", explanation: "For an integrand whose only \\(x\\)-dependence is a linear bracket raised to a power, integrate as if the argument were \\(x\\) (giving \\(\\left(ax+b\\right)^{n+1}/\\left(n+1\\right)\\)), then divide by the inner coefficient \\(a\\) to undo the chain rule. The exclusion \\(n = -1\\) avoids dividing by \\(n+1 = 0\\) — that case uses the log rule.  \\(\\frac{d}{dx}e^{ax+b} = ae^{ax+b}\\) by the chain rule; reading in reverse, the antiderivative needs a divide-by-\\(a\\) to cancel that factor." }, { stepNumber: 2, description: "Split term-by-term.", workingLatex: "\\displaystyle\\int \\left(2x - 1\\right)^3\\,dx + \\displaystyle\\int e^{2x - 1}\\,dx", explanation: "" }, { stepNumber: 3, description: "Apply each formula (\\(a = 2\\) for both).", workingLatex: "= \\frac{\\left(2x - 1\\right)^4}{8} + \\frac{e^{2x - 1}}{2} + C", explanation: "" } ], finalAnswer: "\\(\\frac{\\left(2x - 1\\right)^4}{8} + \\frac{e^{2x - 1}}{2} + C\\)." } },
  { id: "y2in2-068", topicRef: "y2in2", topicTitle: "Integrating f(ax + b) 68", difficulty: "Standard", answerType: "expression", questionText: "Find \\( \\displaystyle\\int [\\sin\\left(2x\\right) + \\sec^2\\left(3x\\right)] \\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["linear-inner", "sum", "trig"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-inner-argument rules we will need.", workingLatex: "\\displaystyle\\int \\sin\\left(ax + b\\right)\\,dx = -\\frac{\\cos\\left(ax + b\\right)}{a} + C \\\\\\\\[2pt] \\displaystyle\\int \\sec^{2}\\left(ax + b\\right)\\,dx = \\frac{\\tan\\left(ax + b\\right)}{a} + C", explanation: "Two things to remember: the leading minus from \\(\\int \\sin = -\\cos\\), and the divide-by-\\(a\\) from the chain rule.  Base antiderivative: \\(\\int \\sec^2 x\\,dx = \\tan x\\). Apply the linear-inner-argument divide-by-\\(a\\)." }, { stepNumber: 2, description: "Split term-by-term.", workingLatex: "\\displaystyle\\int \\sin 2x\\,dx + \\displaystyle\\int \\sec^2 3x\\,dx", explanation: "" }, { stepNumber: 3, description: "Apply each formula.", workingLatex: "= -\\frac{\\cos 2x}{2} + \\frac{\\tan 3x}{3} + C", explanation: "\\(a = 2\\) for sine; \\(a = 3\\) for secant-squared." } ], finalAnswer: "\\(-\\frac{\\cos 2x}{2} + \\frac{\\tan 3x}{3} + C\\)." } },
  { id: "y2in2-069", topicRef: "y2in2", topicTitle: "Integrating f(ax + b) 69", difficulty: "Challenge", answerType: "expression", questionText: "Find \\( \\displaystyle\\int \\frac{3}{\\sqrt{4 - 2x}} \\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["linear-inner", "root"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-inner-argument rule.", workingLatex: "\\displaystyle\\int \\left(ax + b\\right)^{n}\\,dx = \\frac{\\left(ax + b\\right)^{n+1}}{a\\left(n+1\\right)} + C \\quad \\left(n \\ne -1\\right)", explanation: "For an integrand whose only \\(x\\)-dependence is a linear bracket raised to a power, integrate as if the argument were \\(x\\) (giving \\(\\left(ax+b\\right)^{n+1}/\\left(n+1\\right)\\)), then divide by the inner coefficient \\(a\\) to undo the chain rule. The exclusion \\(n = -1\\) avoids dividing by \\(n+1 = 0\\) — that case uses the log rule." }, { stepNumber: 2, description: "Pull constant out, rewrite radical as a negative fractional power.", workingLatex: "\\displaystyle\\int \\frac{3}{\\sqrt{4 - 2x}}\\,dx = 3\\displaystyle\\int \\left(4 - 2x\\right)^{-\\tfrac{1}{2}}\\,dx", explanation: "Now the integrand is in the standard \\(\\left(ax+b\\right)^n\\) form, ready for the power rule." }, { stepNumber: 3, description: "Identify \\(a = -2\\), \\(n = -\\frac{1}{2}\\).", workingLatex: "a\\left(n+1\\right) = -2 \\cdot \\frac{1}{2} = -1", explanation: "" }, { stepNumber: 4, description: "Apply the formula.", workingLatex: "= 3 \\cdot \\frac{\\left(4 - 2x\\right)^{\\tfrac{1}{2}}}{-1} + C = -3\\sqrt{4 - 2x} + C", explanation: "" } ], finalAnswer: "\\(-3\\sqrt{4 - 2x} + C\\)." } },
  { id: "y2in2-070", topicRef: "y2in2", topicTitle: "Integrating f(ax + b) 70", difficulty: "Standard", answerType: "expression", questionText: "Find \\( \\displaystyle\\int 5\\cos\\left(\\frac{\\pi x}{4}\\right) \\,dx \\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["linear-inner", "trig"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-inner-argument rule.", workingLatex: "\\displaystyle\\int \\cos\\left(ax + b\\right)\\,dx = \\frac{\\sin\\left(ax + b\\right)}{a} + C", explanation: "No sign flip (unlike sine) — \\(\\int \\cos = +\\sin\\). Only the divide-by-\\(a\\) chain-rule correction." }, { stepNumber: 2, description: "Pull the constant out, identify \\(a = \\frac{\\pi}{4}\\).", workingLatex: "\\displaystyle\\int 5\\cos\\!\\frac{\\pi x}{4}\\,dx = 5\\displaystyle\\int \\cos\\!\\frac{\\pi x}{4}\\,dx", explanation: "" }, { stepNumber: 3, description: "Apply the formula.", workingLatex: "= 5 \\cdot \\frac{\\sin\\left(\\pi x/4\\right)}{\\pi/4} + C = \\frac{20}{\\pi}\\sin\\left(\\pi x/4\\right) + C", explanation: "\\(\\frac{1}{a} = \\frac{4}{\\pi}\\), so the prefactor is \\(5 \\cdot \\frac{4}{\\pi} = \\frac{20}{\\pi}\\)." } ], finalAnswer: "\\(\\frac{20}{\\pi}\\sin\\left(\\frac{\\pi x}{4}\\right) + C\\)." } },
  { id: "y2in2-071", topicRef: "y2in2", topicTitle: "Integrating f(ax + b) 71", difficulty: "Challenge", answerType: "expression", questionText: "Find \\( \\displaystyle\\int [\\csc^2\\left(x/3\\right) - 3\\sec\\left(2x\\right)\\tan\\left(2x\\right)] \\,dx \\).", marks: 4, examStyle: false, yearCreated: 2026, tags: ["linear-inner", "trig", "sum"], workedSolution: { steps: [ { stepNumber: 1, description: "State the linear-inner-argument rules we will need.", workingLatex: "\\displaystyle\\int \\csc^{2}\\left(ax + b\\right)\\,dx = -\\frac{\\cot\\left(ax + b\\right)}{a} + C \\\\\\\\[2pt] \\displaystyle\\int \\sec\\left(ax + b\\right)\\tan\\left(ax + b\\right)\\,dx = \\frac{\\sec\\left(ax + b\\right)}{a} + C", explanation: "Base: \\(\\int \\csc^2 x\\,dx = -\\cot x\\) (mind the minus). Then divide by \\(a\\).  Base: \\(\\int \\sec x\\tan x\\,dx = \\sec x\\). Divide by \\(a\\)." }, { stepNumber: 2, description: "Split term-by-term, pull constants out.", workingLatex: "\\displaystyle\\int \\csc^2\\left(x/3\\right)\\,dx - 3\\displaystyle\\int \\sec\\left(2x\\right)\\tan\\left(2x\\right)\\,dx", explanation: "" }, { stepNumber: 3, description: "Apply the \\(\\csc^2\\) formula with \\(a = \\frac{1}{3}\\).", workingLatex: "\\displaystyle\\int \\csc^2\\left(x/3\\right)\\,dx = -\\frac{\\cot\\left(x/3\\right)}{1/3} = -3\\cot\\left(x/3\\right)", explanation: "" }, { stepNumber: 4, description: "Apply the \\(\\sec\\tan\\) formula with \\(a = 2\\).", workingLatex: "3\\displaystyle\\int \\sec\\left(2x\\right)\\tan\\left(2x\\right)\\,dx = 3 \\cdot \\frac{\\sec 2x}{2} = \\frac{3}{2}\\sec 2x", explanation: "" }, { stepNumber: 5, description: "Combine.", workingLatex: "\\displaystyle\\int [\\csc^2\\left(x/3\\right) - 3\\sec\\left(2x\\right)\\tan\\left(2x\\right)]\\,dx = -3\\cot\\left(x/3\\right) - \\frac{3}{2}\\sec 2x + C", explanation: "" } ], finalAnswer: "\\(-3\\cot\\left(x/3\\right) - \\frac{3}{2}\\sec 2x + C\\)." } },
];
